const LS = {
  get(k, d = null) { try { const v = localStorage.getItem('mh:' + k); return v ? JSON.parse(v) : d; } catch (e) { return d; } },
  set(k, v) { try { const s = JSON.stringify(v); if (s.length < 600000) localStorage.setItem('mh:' + k, s); } catch (e) { /* kuota penuh: abaikan */ } },
  del(k) { try { localStorage.removeItem('mh:' + k); } catch (e) { } },
  clearPrefix(p) { try { Object.keys(localStorage).forEach((k) => { if (k.indexOf('mh:' + p) === 0) localStorage.removeItem(k); }); } catch (e) { } }
};

/** sessionStorage: token login disimpan PER TAB, sehingga dua akun di dua tab tidak saling tertukar saat refresh. */
