const IMG = {};   // cache blob URL gambar dari Drive
async function imgUrl(fileId) {
  if (IMG[fileId]) return IMG[fileId];
  const f = await API.run('file.get', { file_id: fileId }); if (!f.b64) return null;
  const bin = atob(f.b64); const a = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return (IMG[fileId] = URL.createObjectURL(new Blob([a], { type: f.mime })));
}
function posterHtml(i, cls = '') {
  const l = (i.lampiran || [])[0] || {}; const tone = i.jenis === 'Safety Alert' ? 'alert' : i.jenis === 'Kampanye K3' ? 'k3' : '';
  const img = l.file_id && /PNG|JPG/i.test(l.tipe) ? `<img data-img="${esc(l.file_id)}" alt="">` : '';
  return `<div class="poster ${tone} ${cls}" ${goAttr('info-detail', { id: i.info_id })}>${img}<div class="row wrap gap4">${pill(i.prioritas === 'Mendesak' ? 'Mendesak' : 'Biasa', i.jenis)}${i.wajib && !i.konfirmasi ? '<span class="pill warn">' + ic('task_alt') + 'Perlu konfirmasi</span>' : ''}</div><div class="pt mt8 clamp2">${esc(i.judul)}</div><div class="small" style="opacity:.85">s/d ${tgl(i.selesai)}</div></div>`;
}
function hydrateImgs(root) { $$('img[data-img]', root).forEach(async (im) => { try { const u = await imgUrl(im.dataset.img); if (u) im.src = u; else im.remove(); } catch (e) { im.remove(); } }); }

