P.hoap = async (el, p) => {
  const ym = p.ym || todayStr().slice(0, 7); const months = [0, 1, 2].map((k) => { const d = new Date(Date.UTC(+ym.slice(0, 4), +todayStr().slice(5, 7) - 1 - k, 1)); return d.toISOString().slice(0, 7); });
  const draw = (d) => {
    const q = Outbox.q.filter((x) => x.action === 'hoap.submit');
    el.innerHTML = ph('HOAP Saya', 'Target dan capaian Hazard Report, Hanwha Way, HOT5, dan Inspeksi Anda.', `<select class="sel" id="hm" style="width:180px">${months.map((m) => `<option value="${m}" ${m === ym ? 'selected' : ''}>${ymLabel(m)}</option>`).join('')}</select><button class="btn pri" data-go="hoap-input">${ic('add_circle')}Input HOAP</button>`) +
      `<div class="grid g4">${d.programs.map((x) => `<div class="card pad"><div class="row between"><div class="b">${esc(x.program)}</div>${x.achieved ? pill('Achieved') : pill('Belum Achieved', 'Belum')}</div><div class="row mt12" style="align-items:baseline"><span style="font:800 28px/1 var(--f-head)" class="num">${fmtN(x.aktual)}</span><span class="sub">/ ${fmtN(x.target)} target</span></div><div class="mt12">${bar(x.pct, x.achieved ? 'ok' : '')}</div><div class="small sub mt8">${fmtP(x.pct)} ${x.pctRaw > 100 ? '(aktual ' + fmtP(x.pctRaw) + ')' : ''}</div></div>`).join('')}</div>
      <div class="card mt16"><div class="hd"><h3>Riwayat Kiriman Saya</h3><span class="small sub">${d.history.length} terakhir</span></div><div class="list">${q.map((x) => `<div class="li"><div class="lic">${ic('cloud_off')}</div><div class="grow"><div class="b">${esc(x.payload.program)} — ${esc(x.payload.lokasi)}</div><div class="small sub clamp2">${esc(x.payload._ringkas || '')}</div></div>${pill(x.status === 'failed' ? 'Gagal' : x.status === 'sending' ? 'Sedang Dikirim' : 'Draft Lokal')}</div>`).join('')}
      ${d.history.map((s) => `<div class="li"><div class="lic">${ic(s.program === 'Inspeksi' ? 'search' : s.program === 'HOT5' ? 'local_fire_department' : s.program === 'Hanwha Way' ? 'verified_user' : 'warning')}</div><div class="grow"><div class="b">${esc(s.program)}${s.jenis ? ' · ' + esc(s.jenis) : ''} · ${esc(s.lokasi)}</div><div class="small sub clamp2">${esc(s.uraian)}</div><div class="small muted">${tgl(s.tanggal)} · risiko ${esc(s.risiko)}</div></div>${pill('Terkirim')}</div>`).join('') || (q.length ? '' : empty('history', 'Belum ada kiriman', 'Mulai dengan menekan Input HOAP.'))}</div></div>`;
    $('#hm').onchange = (e) => go('hoap', { ym: e.target.value });
  };
  loadPage('hoap:' + ym, 'hoap.mine', { ym }, draw, () => (el.innerHTML = skPage()));
};
