  if (it.action === 'form.submit') { toast(res && res.temuan ? `Formulir terkirim. ${res.temuan} temuan "Tidak OK" otomatis menjadi RTP.` : 'Formulir berhasil dikirim.', 'ok'); Data.drop('home'); }
  if (it.action === 'doc.confirm') { toast('Konfirmasi baca tercatat.', 'ok'); Data.drop('docs'); }
