/* ── W-06 Perpustakaan Prosedur ── */
P.prosedur = async (el, p) => {
  const draw = (d) => {
    const w = d.rows.filter((r) => r.wajib && r.wajib.status !== 'SUDAH').length;
    const aktif = (r) => r.status === 'ACTIVE';
    const jenisAda = DOC_JENIS.concat(['Kebijakan', 'JSA']).filter((j) => d.rows.some((r) => r.jenis === j));
    const lvls = uniq(d.rows.map((r) => (r.level === 'Corporate' ? 'Corporate' : 'Site ' + (r.site || '')))).sort();
    const depts = uniq(d.rows.map((r) => r.dept).filter(Boolean)).sort();
    el.innerHTML = ph('Perpustakaan Prosedur', 'Prosedur, instruksi kerja, standar, manual, dan formulir. Anda melihat dokumen sesuai kewenangan Anda.', inMenu('prosedur-kelola') ? `<button class="btn" data-go="prosedur-kelola">${ic('edit_document')}Kelola Prosedur</button>` : '') +
      (w ? `<div class="note warn mb16">${ic('schedule')}<div>Anda memiliki <b>${w}</b> dokumen wajib baca yang belum dikonfirmasi.</div></div>` : '') + '<div id="dtbl"></div>';
    TableView($('#dtbl'), {
      rows: d.rows, pageSize: 25, search: (r) => r.nomor + ' ' + r.judul + ' ' + r.alasan, searchPh: 'Cari nomor atau nama dokumen…', exportName: 'perpustakaan_prosedur',
      emptyIcon: 'menu_book', emptyTitle: 'Belum ada dokumen', emptyMsg: 'Dokumen yang berlaku untuk Anda akan tampil di sini.',
      filters: [
        { k: 'jenis', l: 'Jenis dokumen', opts: jenisAda, fn: (r, v) => r.jenis === v },
        { k: 'status', l: 'Status', all: 'Semua status', def: 'A', opts: [['A', 'Active'], ['N', 'Tidak aktif']], fn: (r, v) => (v === 'A' ? aktif(r) : !aktif(r)) },
        { k: 'level', l: 'Level / Site', opts: lvls, fn: (r, v) => (r.level === 'Corporate' ? 'Corporate' : 'Site ' + (r.site || '')) === v },
        ...(depts.length ? [{ k: 'dept', l: 'Departemen', opts: depts, fn: (r, v) => r.dept === v }] : []),
        ...(d.rows.some((r) => r.wajib) ? [{ k: 'wajib', l: 'Wajib baca', opts: [['1', 'Ditugaskan ke saya']], fn: (r) => !!r.wajib }] : [])
      ],
      cols: [
        { k: 'judul', l: 'Nama Dokumen', x: (r) => `<div class="b">${esc(r.judul)}</div><div class="small sub">${esc(r.jenis)} · <span class="pill outline lc">${esc(r.level)}${r.site ? ' · ' + esc(r.site) : ''}</span>${r.dept ? ' · ' + esc(r.dept) : ''}</div>` },
        { k: 'nomor', l: 'No Dokumen', cls: 'mono', x: (r) => esc(r.nomor) },
        { k: 'rev', l: 'Revisi', x: (r) => `<b>${esc(r.rev)}</b>${r.alasan ? `<div class="small sub clamp2">${esc(r.alasan)}</div>` : ''}`, csv: (r) => r.rev + (r.alasan ? ' - ' + r.alasan : '') },
        { k: 'status', l: 'Status', x: (r) => (aktif(r) ? pill('ACTIVE') : '<span class="pill outline">Tidak aktif</span>') + (r.wajib ? `<div class="small mt8">${pill(r.wajib.status)}</div>` : ''), csv: (r) => (aktif(r) ? 'Active' : 'Tidak aktif') }
      ],
      onRow: (r) => go('prosedur-detail', { id: r.doc_id })
    });
  };
  loadPage('docs', 'doc.list', {}, draw, () => (el.innerHTML = skPage()));
};

/* ── Pustaka Formulir & JSA (tanpa approval) ── */
P.pustaka = async (el) => {
  const draw = (d) => {
    const m = d.meta; const IC = { Formulir: 'assignment', JSA: 'health_and_safety' };
    const dlg = (r, base) => {
      const e = r || {}; let file = e.file_id ? { file_id: e.file_id, nama: e.file_nama } : null; const lvlFix = !!r; const canSite = m.sites.length > 0;
      const mm = modal({ title: r ? 'Ubah Formulir / JSA' : (base ? 'Salin ke site' : 'Tambah Formulir / JSA'), size: '', body: `<div class="fgrid">
        <div class="fld"><label>Jenis</label><select class="sel" id="pJenis" ${lvlFix ? 'disabled' : ''}><option>Formulir</option><option>JSA</option></select></div>
        <div class="fld"><label>Berlaku untuk</label><select class="sel" id="pLv" ${lvlFix ? 'disabled' : ''}>${m.canCorp ? '<option value="Corporate">Semua site (Corporate)</option>' : ''}${canSite ? '<option value="Site">Site tertentu</option>' : ''}</select></div>
        <div class="fld" id="pSiteW"><label>Site</label><select class="sel" id="pSite" ${lvlFix ? 'disabled' : ''}>${m.sites.map((x) => `<option value="${x.site_id}">${esc(x.kode)}</option>`).join('')}</select></div>
        <div class="fld" id="pDeptW"><label>Departemen pemilik${m.isAdm ? ' (opsional)' : ''}</label><select class="sel" id="pDept"><option value="">${m.isAdm ? '(semua / umum)' : 'Pilih departemen…'}</option>${m.depts.filter((x) => m.isAdm || m.myDepts.indexOf(x.kode) >= 0).map((x) => `<option value="${x.kode}">${esc(x.nama)}</option>`).join('')}</select></div>
        <div class="fld"><label>No Dokumen</label><input class="inp mono" id="pNo" value="${esc(e.nomor || '')}" placeholder="Contoh: HMSI-FRM-SHE-028"></div>
        <div class="fld"><label>Revisi</label><input class="inp" id="pRev" value="${esc(e.rev || 'Rev.0')}"></div>
        <div class="fld" style="grid-column:1/-1"><label>Nama dokumen</label><input class="inp" id="pJudul" value="${esc(e.judul || '')}"></div>
        <div class="fld" style="grid-column:1/-1"><label>Keterangan revisi / catatan</label><textarea class="inp" id="pKet" rows="2">${esc(e.keterangan || '')}</textarea></div>
        <div class="fld" style="grid-column:1/-1"><label>Berkas (PDF, Word, atau Excel)</label><div class="row gap8"><button class="btn" id="pUp">${ic('upload_file')}Pilih berkas</button><span class="small sub" id="pUpT">${file ? esc(file.nama) : 'Belum ada berkas'}</span></div></div></div>
        <div class="hint mt8">Tanpa approval. JSA untuk izin kerja khusus tetap diajukan lewat menu Izin Kerja Khusus (PTW) dan diperiksa di sana.</div>`,
        foot: '<button class="btn" data-x>Batal</button><button class="btn pri" id="pOk">Simpan</button>' });
      const $m = (i) => mm.$('#' + i); $m('pJenis').value = e.jenis || 'Formulir'; $m('pLv').value = e.level || (m.canCorp ? 'Corporate' : 'Site'); if (e.site_id) $m('pSite').value = e.site_id; if (e.dept) $m('pDept').value = e.dept;
      const sync = () => { $m('pSiteW').classList.toggle('hide', $m('pLv').value === 'Corporate'); }; $m('pLv').onchange = sync; sync();
      $m('pUp').onclick = async () => { const lv = $m('pLv').value; const fs = await pickUpload('application/pdf,.doc,.docx,.xls,.xlsx', { modul: 'pustaka', site_id: lv === 'Site' ? $m('pSite').value : '' }, false); if (fs[0]) { file = fs[0]; $m('pUpT').textContent = file.nama; } };
      $m('pOk').onclick = async () => {
        const lv = $m('pLv').value; const v = { id: e.pustaka_id || '', jenis: $m('pJenis').value, level: lv, site_id: lv === 'Site' ? $m('pSite').value : '', pemilik: $m('pDept').value, nomor: $m('pNo').value.trim(), rev: $m('pRev').value.trim(), judul: $m('pJudul').value.trim(), keterangan: $m('pKet').value.trim(), file_id: file ? file.file_id : '', file_nama: file ? file.nama : '' };
        if (!v.judul || !v.nomor) return toast('Isi nama dokumen dan nomor.', 'warn'); if (!v.file_id) return toast('Pilih berkas terlebih dahulu.', 'warn');
        try { await busy($m('pOk'), () => API.run('pustaka.save', v, uid())); mm.close(); toast('Tersimpan.', 'ok'); Data.drop('pustaka'); P.pustaka(el); } catch (er) { toast(er.message || 'Gagal menyimpan.', 'bad'); }
      };
    };
    const salin = (r) => {
      const mm = modal({ title: 'Salin ke site', body: `<p class="sub">Salinan menjadi milik site dan dapat Anda ubah tanpa memengaruhi dokumen Corporate.</p><div class="fld mt16"><label>Site tujuan</label><select class="sel" id="sSite">${m.sites.map((x) => `<option value="${x.site_id}">${esc(x.kode)}</option>`).join('')}</select></div>${m.isAdm ? '' : `<div class="fld mt16"><label>Departemen</label><select class="sel" id="sDept">${m.depts.filter((x) => m.myDepts.indexOf(x.kode) >= 0).map((x) => `<option value="${x.kode}">${esc(x.nama)}</option>`).join('')}</select></div>`}`, foot: '<button class="btn" data-x>Batal</button><button class="btn pri" id="sOk">Salin</button>' });
      mm.$('#sOk').onclick = async () => { try { await busy(mm.$('#sOk'), () => API.run('pustaka.salin', { id: r.pustaka_id, site_id: mm.$('#sSite').value, pemilik: mm.$('#sDept') ? mm.$('#sDept').value : '' }, uid())); mm.close(); toast('Disalin ke site.', 'ok'); Data.drop('pustaka'); P.pustaka(el); } catch (er) { toast(er.message || 'Gagal menyalin.', 'bad'); } };
    };
    const lvls = uniq(d.rows.map((r) => (r.level === 'Corporate' ? 'Corporate' : 'Site ' + (r.site || '')))).sort(); const dn = {}; m.depts.forEach((x) => (dn[x.kode] = x.nama));
    el.innerHTML = ph('Formulir & JSA', 'Formulir teknis dan JSA acuan. Tanpa approval; JSA izin kerja khusus tetap diperiksa lewat PTW.', (m.canCorp ? `<button class="btn" id="pBulk">${ic('upload_file')}Unggah massal</button>` : '') + (m.canAdd ? `<button class="btn pri" id="pAdd">${ic('add')}Tambah</button>` : '')) + '<div id="ptbl"></div>';
    const tv = TableView($('#ptbl'), {
      rows: d.rows, pageSize: 25, search: (r) => r.nomor + ' ' + r.judul + ' ' + r.keterangan, searchPh: 'Cari nomor atau nama…', exportName: 'formulir_jsa', emptyIcon: 'assignment', emptyTitle: 'Belum ada formulir atau JSA',
      filters: [
        { k: 'jenis', l: 'Jenis', opts: ['Formulir', 'JSA'], fn: (r, v) => r.jenis === v },
        { k: 'status', l: 'Status', all: 'Semua status', def: 'A', opts: [['A', 'Active'], ['N', 'Tidak aktif']], fn: (r, v) => (v === 'A' ? r.status === 'AKTIF' : r.status !== 'AKTIF') },
        { k: 'level', l: 'Level / Site', opts: lvls, fn: (r, v) => (r.level === 'Corporate' ? 'Corporate' : 'Site ' + (r.site || '')) === v },
        { k: 'dept', l: 'Departemen', all: 'Semua departemen', opts: [...m.depts.map((x) => [x.kode, x.nama]), ['-', 'Umum (tanpa departemen)']], fn: (r, v) => (v === '-' ? !r.dept : r.dept === v) }
      ],
      cols: [
        { k: 'judul', l: 'Nama Dokumen', x: (r) => `<div class="b">${esc(r.judul)}</div><div class="small sub">${esc(r.jenis)} · <span class="pill outline lc">${esc(r.level)}${r.site ? ' · ' + esc(r.site) : ''}</span>${r.dept ? ' · ' + esc(dn[r.dept] || r.dept) : ''}${r.sumber_id ? ' · salinan Corporate' : ''}</div>` },
        { k: 'nomor', l: 'No Dokumen', cls: 'mono', x: (r) => esc(r.nomor) },
        { k: 'rev', l: 'Revisi', x: (r) => `<b>${esc(r.rev)}</b>${r.keterangan ? `<div class="small sub clamp2">${esc(r.keterangan)}</div>` : ''}`, csv: (r) => r.rev + (r.keterangan ? ' - ' + r.keterangan : '') },
        { k: 'status', l: 'Status', x: (r) => (r.status === 'AKTIF' ? pill('ACTIVE') : '<span class="pill outline">Tidak aktif</span>'), csv: (r) => (r.status === 'AKTIF' ? 'Active' : 'Tidak aktif') },
        { k: 'aksi', l: '', nosort: true, noexp: true, x: (r) => `<div class="row gap8" style="justify-content:flex-end"><button class="btn sm" data-op="${r.pustaka_id}">${ic('visibility', 's18')}Buka</button>${r.level === 'Corporate' && r.status === 'AKTIF' && m.sites.length ? `<button class="btn sm" data-sl="${r.pustaka_id}">${ic('content_copy', 's18')}Salin</button>` : ''}${r.can ? `<button class="btn sm" data-ed="${r.pustaka_id}">${ic('edit', 's18')}Ubah</button><button class="btn sm" data-ar="${r.pustaka_id}">${r.status === 'AKTIF' ? 'Nonaktifkan' : 'Aktifkan'}</button>` : ''}</div>` }
      ],
      after: (box) => {
        const g = (id) => d.rows.find((x) => x.pustaka_id === id);
        $$('[data-op]', box).forEach((b) => (b.onclick = () => { const r = g(b.dataset.op); openFile(r.file_id, r.file_nama || r.nomor); }));
        $$('[data-sl]', box).forEach((b) => (b.onclick = () => salin(g(b.dataset.sl))));
        $$('[data-ed]', box).forEach((b) => (b.onclick = () => dlg(g(b.dataset.ed))));
        $$('[data-ar]', box).forEach((b) => (b.onclick = async () => { const r = g(b.dataset.ar); try { await busy(b, () => API.run('pustaka.arsip', { id: r.pustaka_id, aktif: r.status !== 'AKTIF' }, uid())); Data.drop('pustaka'); P.pustaka(el); } catch (er) { toast(er.message || 'Gagal.', 'bad'); } }));
      }
    });
    /* Unggah massal (khusus SHEC Corporate): pilih banyak berkas, periksa nomor/nama/jenis/departemen, simpan sekaligus */
    const bulk = async () => {
      const fs = await pickFiles('application/pdf,.doc,.docx,.xls,.xlsx', true); if (!fs.length) return;
      if (fs.length > 100) return toast('Maksimal 100 berkas sekali unggah. Pilih lebih sedikit.', 'warn');
      let closed = false; const mm = modal({ title: 'Unggah massal Formulir / JSA', size: 'xl', body: '<div id="bkB"></div>', foot: '<button class="btn" data-x>Tutup</button><button class="btn pri" id="bkOk" disabled>Simpan semua</button>', onClose: () => { closed = true; } });
      const box = mm.$('#bkB'); const rows = []; const gagalUp = [];
      const guess = (up) => {
        const raw = String(up.nama || '').replace(/\.[A-Za-z0-9]{1,5}$/, ''); const nm = /\b[A-Z]{2,6}(?:-[A-Z0-9]{1,8}){2,5}\b/.exec(raw); const nomor = nm && /\d/.test(nm[0]) ? nm[0] : '';
        const rv = /\bRev\.?\s{0,2}(\d{1,2})\b/i.exec(raw); let judul = raw.replace(/_/g, ' '); if (nomor) judul = judul.replace(nomor, ''); judul = judul.replace(/\bRev\.?\s{0,2}\d{1,2}\b/i, '').replace(/^[\s\-–]+|[\s\-–]+$/g, '').replace(/\s{2,}/g, ' ');
        return { file_id: up.file_id, file_nama: up.nama, jenis: /\bJSA\b/i.test(raw) ? 'JSA' : 'Formulir', nomor, judul: judul || raw, rev: rv ? 'Rev.' + rv[1] : 'Rev.0', pemilik: '', err: '' };
      };
      for (let i = 0; i < fs.length && !closed; i++) {
        box.innerHTML = `<div class="row gap12"><div class="spin"></div><div>Mengunggah berkas ${i + 1} dari ${fs.length}… <span class="small sub">${esc(fs[i].name)}</span></div></div>`;
        try { const r = await uploadFile(fs[i], { modul: 'pustaka', site_id: '' }); rows.push(guess({ file_id: r.file_id, nama: r.nama })); } catch (er) { gagalUp.push(fs[i].name + ' (' + (er.message || 'gagal') + ')'); }
      }
      if (closed) { Data.drop('pustaka'); return; }
      const deptOpts = (cur) => `<option value="">(umum)</option>${m.depts.map((x) => `<option value="${x.kode}" ${x.kode === cur ? 'selected' : ''}>${esc(x.nama)}</option>`).join('')}`;
      const paint = () => {
        mm.$('#bkOk').disabled = !rows.length;
        box.innerHTML = `<div class="note info mb12">${ic('info')}<div>${rows.length} berkas siap. Nomor dan nama dibaca dari nama berkas (nomor berpola seperti HMSI-FRM-SHE-028); semuanya dapat diubah. Semua tersimpan sebagai <b>Corporate (berlaku untuk semua site)</b>.</div></div>${gagalUp.length ? `<div class="note warn mb12">${ic('warning')}<div>Tidak terunggah: ${esc(gagalUp.join('; '))}</div></div>` : ''}
          <div class="row wrap gap12 mb12" style="align-items:flex-end"><div class="fld"><label>Jenis untuk semua</label><select class="sel sm" id="bkJ"><option value="">— pilih —</option><option>Formulir</option><option>JSA</option></select></div><div class="fld"><label>Departemen untuk semua</label><select class="sel sm" id="bkD"><option value="">— pilih —</option><option value="-">(umum / semua departemen)</option>${m.depts.map((x) => `<option value="${x.kode}">${esc(x.nama)}</option>`).join('')}</select></div><button class="btn sm" id="bkAp">Terapkan ke semua</button></div>
          ${rows.length ? `<style>#bkB .tbl td, #bkB .tbl th { padding: 8px; }</style><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Berkas</th><th>Jenis</th><th>No Dokumen</th><th>Nama dokumen</th><th>Revisi</th><th>Departemen</th><th></th></tr></thead><tbody>${rows.map((r, i) => `<tr><td class="small" style="max-width:150px;word-break:break-all">${esc(r.file_nama)}${r.err ? `<div class="err-t">${ic('error', 's16')}${esc(r.err)}</div>` : ''}</td><td><select class="sel sm" style="min-width:104px" data-i="${i}" data-k="jenis"><option ${r.jenis === 'Formulir' ? 'selected' : ''}>Formulir</option><option ${r.jenis === 'JSA' ? 'selected' : ''}>JSA</option></select></td><td><input class="inp sm mono ${r.err ? 'bad' : ''}" style="min-width:150px" data-i="${i}" data-k="nomor" value="${esc(r.nomor)}" placeholder="HMSI-FRM-SHE-028"></td><td><input class="inp sm" style="min-width:190px" data-i="${i}" data-k="judul" value="${esc(r.judul)}"></td><td><input class="inp sm" style="width:76px" data-i="${i}" data-k="rev" value="${esc(r.rev)}"></td><td><select class="sel sm" style="min-width:150px" data-i="${i}" data-k="pemilik">${deptOpts(r.pemilik)}</select></td><td><button class="btn ghost icon sm" data-rm="${i}" aria-label="Hapus baris">${ic('close')}</button></td></tr>`).join('')}</tbody></table></div>` : '<div class="empty"><div class="b">Tidak ada berkas yang tersisa.</div></div>'}`;
        mm.$('#bkAp').onclick = () => { const j = mm.$('#bkJ').value, dd = mm.$('#bkD').value; if (!j && !dd) return toast('Pilih jenis atau departemen dulu.', 'warn'); rows.forEach((r) => { if (j) r.jenis = j; if (dd) r.pemilik = dd === '-' ? '' : dd; }); paint(); };
        $$('[data-rm]', box).forEach((b) => (b.onclick = () => { rows.splice(+b.dataset.rm, 1); paint(); }));
      };
      const onEdit = (e) => { const t = e.target; if (t.dataset && t.dataset.k && rows[+t.dataset.i]) { rows[+t.dataset.i][t.dataset.k] = t.value; rows[+t.dataset.i].err = ''; } };
      box.addEventListener('input', onEdit); box.addEventListener('change', onEdit); paint();
      mm.$('#bkOk').onclick = async () => {
        const bad = rows.find((r) => String(r.nomor).trim() === '' || String(r.judul).trim().length < 3); if (bad) return toast('Lengkapi nomor dan nama (minimal 3 huruf) untuk semua baris.', 'warn');
        const keys = {}; for (const r of rows) { const k = r.jenis + '|' + r.nomor.trim().toLowerCase(); if (keys[k]) return toast('Nomor ' + r.nomor + ' muncul dua kali pada daftar.', 'warn'); keys[k] = 1; }
        const res = await busy(mm.$('#bkOk'), () => API.run('pustaka.bulk', { rows: rows.map((r) => ({ file_id: r.file_id, file_nama: r.file_nama, jenis: r.jenis, nomor: r.nomor.trim(), judul: r.judul.trim(), rev: r.rev.trim(), pemilik: r.pemilik })) }, uid())); if (!res) return;
        Data.drop('pustaka'); const fail = {}; res.gagal.forEach((g) => (fail[g.i] = g.pesan)); const keep = []; rows.forEach((r, i) => { if (fail[i]) { r.err = fail[i]; keep.push(r); } });
        rows.length = 0; keep.forEach((r) => rows.push(r));
        if (!rows.length) { mm.close(); toast(res.ok + ' formulir/JSA tersimpan.', 'ok'); P.pustaka(el); return; }
        toast(res.ok + ' tersimpan, ' + rows.length + ' perlu diperbaiki (lihat pesan merah).', 'warn'); paint();
      };
    };
    const a = $('#pAdd'); if (a) a.onclick = () => dlg(null);
    const bk = $('#pBulk'); if (bk) bk.onclick = () => bulk();
  };
  loadPage('pustaka', 'pustaka.list', {}, draw, () => (el.innerHTML = skPage()));
};

/* ── W-07 Detail prosedur + konfirmasi baca ── */
P['prosedur-detail'] = async (el, p) => {
  const draw = (d) => {
    const x = d.doc, w = d.wajib; const opened = LS.get('opened:' + x.doc_id) || (w && w.dibuka); const done = w && w.status === 'SUDAH';
    el.innerHTML = `<div style="max-width:980px;margin:0 auto">${ph(x.judul, '', '', 'Kembali')}<div class="card pad"><div class="row wrap gap8"><span class="tag">${esc(x.nomor)}</span><span class="tag">${esc(x.rev)}</span>${pill(x.status)}<span class="pill outline lc">${esc(x.level)}</span><span class="pill outline lc">${esc(x.jenis)}</span><span class="small sub">Berlaku sejak ${tgl(x.berlaku_sejak)}</span></div>
      <div class="viewer mt16" style="min-height:220px"><div class="center col" style="align-items:center">${ic('picture_as_pdf', 's48')}<div class="b" style="color:#fff">${esc(x.file_nama || x.nomor + '.pdf')}</div><button class="btn pri mt8" id="openDoc">${ic('visibility')}Buka dokumen</button><div class="small">Pratinjau dibuka di jendela modal — tidak meninggalkan aplikasi.</div></div></div>
      ${d.versions.length > 1 ? `<details class="mt16"><summary class="b" style="cursor:pointer">Riwayat versi (${d.versions.length})</summary><div class="list mt8">${d.versions.map((v) => `<div class="li"><div class="grow"><b>${esc(v.rev)}</b> <span class="small sub">berlaku ${tgl(v.berlaku)}</span></div>${pill(v.status)}</div>`).join('')}</div></details>` : ''}</div>
      ${esignCard(d)}
      ${w ? `<div class="card pad mt16"><div class="note ${done ? 'ok' : w.status === 'TERLAMBAT' ? 'bad' : 'warn'}">${ic(done ? 'task_alt' : 'schedule')}<div>${done ? `Anda sudah mengonfirmasi membaca dokumen ini pada <b>${tglJam(w.dikonfirmasi_at)}</b>.` : `<b>Wajib dibaca sebelum ${tgl(w.batas)}</b>. Buka dokumen terlebih dahulu, lalu konfirmasi.`}</div></div>
        ${done ? '' : `${opened ? '' : '<div class="hint mt8">Buka dokumen terlebih dahulu agar pertanyaan dapat diisi.</div>'}<div class="col gap16 mt16 ${opened ? '' : 'dim'}" id="wq">${(w.pertanyaan || []).map((q, qi) => `<div class="fld"><label><b>${qi + 1}.</b> ${esc(q.q)} <span class="req">*</span></label><textarea class="ta" data-wq="${qi}" maxlength="1000" style="min-height:70px" placeholder="Tulis jawaban Anda…" ${opened ? '' : 'disabled'}></textarea></div>`).join('')}<button class="btn pri lg block" id="cfm" ${opened ? '' : 'disabled'}>${ic('task_alt')}Kirim jawaban &amp; konfirmasi sudah membaca</button><div class="hint center" id="cfmH">Semua pertanyaan wajib dijawab. Jawaban Anda dipakai untuk perbaikan prosedur — bukan penilaian benar/salah.</div></div>`}</div>` : ''}</div>`;
    esignBind(el, d);
    $('#openDoc').onclick = () => { LS.set('opened:' + x.doc_id, 1); if (w && !w.dibuka) { Outbox.push('doc.open', { doc_id: x.doc_id, nomor: x.nomor }, { label: 'Buka dokumen ' + x.nomor }); w.dibuka = true; } openFile(x.file_id, x.file_nama || x.nomor + '.pdf'); const c = $('#cfm'); if (c) { c.disabled = false; $$('[data-wq]', el).forEach((t) => (t.disabled = false)); const q = $('#wq'); if (q) q.classList.remove('dim'); } };
    const c = $('#cfm'); if (c) c.onclick = async () => {
      const jw = $$('[data-wq]', el).map((t) => t.value.trim()); const bad = jw.findIndex((x) => x.length < 3);
      if (bad >= 0) { const t = $$('[data-wq]', el)[bad]; t.focus(); return toast(`Pertanyaan ${bad + 1} wajib dijawab.`, 'warn'); }
      if (!S.online) return toast('Mengirim jawaban perlu koneksi internet.', 'warn');
      const r = await busy(c, () => API.run('doc.confirm', { penetapan_id: w.penetapan_id, jawaban: jw }, uid())); if (!r) return;
      w.status = 'SUDAH'; w.dikonfirmasi_at = nowWib(); Data.put('doc:' + x.doc_id, d); Data.drop('docs'); const h = Data.peek('home'); if (h) { (h.wajib || []).forEach((y) => { if (y.penetapan_id === w.penetapan_id) y.status = 'SUDAH'; }); Data.put('home', h); } toast('Terima kasih — jawaban dan konfirmasi tercatat.', 'ok'); draw(d);
    };
  };
  loadPage('doc:' + p.id, 'doc.get', { id: p.id }, draw, () => (el.innerHTML = skPage()));
};

/* ── W-08 Notification Center ── */
P.notifikasi = async (el) => {
  let tab = 'Semua'; const TABS = { Semua: () => true, Tugas: (n) => ['Tugas', 'Overdue'].indexOf(n.jenis) >= 0, Pengumuman: (n) => ['Pengumuman', 'Mendesak'].indexOf(n.jenis) >= 0, Persetujuan: (n) => ['Persetujuan', 'Selesai', 'Penugasan'].indexOf(n.jenis) >= 0 };
  const draw = (d) => {
    const rows = d.rows.filter(TABS[tab]);
    el.innerHTML = ph('Notification Center', '', `<button class="btn" id="rdAll">${ic('done_all')}Tandai semua dibaca</button>`) + `<div class="card"><div class="tabs" style="padding:0 16px">${Object.keys(TABS).map((t) => `<button data-t="${t}" class="${t === tab ? 'on' : ''}">${t} ${t === 'Semua' && d.unread ? `<span class="pill ora">${d.unread}</span>` : ''}</button>`).join('')}</div>
      <div class="list">${rows.length ? rows.map((n) => `<div class="li ${n.dibaca ? '' : 'unread'}" data-n="${n.notif_id}"><div class="lic" style="${n.jenis === 'Mendesak' || n.jenis === 'Overdue' ? 'background:var(--bad-t);color:var(--bad)' : ''}">${ic({ Tugas: 'task_alt', Pengumuman: 'campaign', Mendesak: 'warning', Persetujuan: 'approval', Overdue: 'alarm', Selesai: 'check_circle', Penugasan: 'admin_panel_settings' }[n.jenis] || 'notifications')}</div><div class="grow"><div class="ttl-i">${esc(n.judul)}</div><div class="small sub clamp2">${esc(n.isi)}</div><div class="xs muted mt8">${esc(relTime(n.created_at))}</div></div>${n.dibaca ? '' : '<i class="udot"></i>'}</div>`).join('') : empty('notifications_off', 'Belum ada notifikasi')}</div></div>`;
    $$('.tabs button', el).forEach((b) => (b.onclick = () => { tab = b.dataset.t; draw(d); }));
    $('#rdAll').onclick = () => { d.rows.forEach((n) => (n.dibaca = true)); d.unread = 0; Data.put('notif', d); Shell.paintBadges(0); draw(d); API.run('notif.read', { all: true }).catch(() => { }); };
    $$('[data-n]', el).forEach((li) => (li.onclick = () => { const n = d.rows.find((x) => x.notif_id === li.dataset.n); if (!n.dibaca) { n.dibaca = true; d.unread = Math.max(0, d.unread - 1); Data.put('notif', d); Shell.paintBadges(d.unread); API.run('notif.read', { ids: [n.notif_id] }).catch(() => { }); } openRef(n.ref_type, n.ref_id); }));
  };
  loadPage('notif', 'notif.list', {}, draw, () => (el.innerHTML = skPage()));
};
function openRef(t, id) {
  if (t === 'mcu' && id) return go('mcu-fu', { id });
  if (t === 'apd' && inMenu('dash-apd')) return go('dash-apd');
  if (t === 'mutasi') { if (inMenu('set-mutasi')) return go('set-mutasi'); return toast('Mutasi diproses oleh Admin Site.', 'info'); }
  if (t === 'keskerja') return go(inMenu('reg-kes') ? 'reg-kes' : 'beranda', { tab: 'isi' }); if (t === 'tspna') return go(inMenu('tsp') ? 'tsp' : 'beranda', { tab: 'na' }); if (t === 'tspdok') return go(inMenu('tsp') ? 'tsp' : 'beranda', { tab: 'dok' }); if (t === 'tsp') return go(inMenu('tsp') ? 'tsp' : 'beranda', { tab: 'rencana' }); if ((t === 'ptw' || t === 'ptwreview') && id) return go(inMenu('ptw') ? 'ptw-detail' : 'beranda', { id }); if (t === 'ptwedit' && id) return go(inMenu('ptw') ? 'ptw-form' : 'beranda', { id }); if (t === 'rtp' && id) return go('rtp-detail', { id }); if (t === 'info' && id) return go('info-detail', { id }); if (t === 'doc' && id) return go('prosedur-detail', { id }); if (t === 'docreview' && id) return go(inMenu('prosedur-kelola') ? 'doc-review' : 'prosedur-detail', { id }); if (t === 'docedit' && id) return go(inMenu('prosedur-kelola') ? 'doc-form' : 'prosedur-detail', { id }); if (t === 'form' && id) return go(inMenu('formulir') ? 'form-hasil' : 'form-isi', { id });
  if (t === 'role') { Shell.refreshBoot(); return toast('Hak akses diperbarui.', 'ok'); } if (t === 'audit' && id && (inMenu('audit-smkp') || inMenu('audit-mgmt'))) return go('audit-detail', { id }); if (t === 'laporan' && inMenu('laporan')) return go('laporan'); if (t === 'lapbln' && inMenu('laporan')) { LS.set('f:lap', Object.assign(LS.get('f:lap', {}), { jenis: 'Bulanan', view: '' })); return go('laporan'); } if (t === 'lapmgg' && inMenu('laporan')) { LS.set('f:lap', Object.assign(LS.get('f:lap', {}), { jenis: 'Mingguan', view: '' })); return go('laporan'); } if (t === 'kplh' && inMenu('dash-kplh')) return go('dash-kplh');
  if (inMenu('tugas')) go('tugas');
}

/* ── W-09 Detail Pengumuman ── */
