const qaBlock = (i) => {
  if (i.konfirmasi) return `<div class="note ok mt16">${ic('task_alt')}<div>Jawaban Anda sudah tercatat — dikonfirmasi ${tglJam(i.konfirmasi_at || nowWib())}. Terima kasih.</div></div>`;
  return `<div class="card mt16" id="qz"><div class="hd"><div class="sec-t"><div class="ib">${ic('rate_review')}</div><h3>Pertanyaan untuk Anda</h3></div><span class="small sub">${i.pertanyaan.length} pertanyaan · wajib dijawab</span></div><div class="bd col gap16">
    <div class="note info">${ic('info')}<div>Baca pengumuman di atas, lalu jawab dengan kata-kata Anda sendiri. Tidak ada jawaban benar atau salah. Konfirmasi baca tercatat setelah semua pertanyaan dijawab.</div></div>
    ${i.pertanyaan.map((q, qi) => `<div class="fld"><label><b>${qi + 1}.</b> ${esc(q.q)} <span class="req">*</span></label><textarea class="ta" data-iq="${qi}" maxlength="1000" style="min-height:70px" placeholder="Tulis jawaban Anda…"></textarea></div>`).join('')}
    <button class="btn pri lg block" id="qzGo">${ic('send')}Kirim jawaban &amp; konfirmasi</button><div class="hint" id="qzOff" ${S.online ? 'hidden' : ''}>Perlu koneksi internet untuk mengirim jawaban.</div></div></div>`;
};
