const scopeSites = () => (S.boot.sites || []).filter((s) => s.status === 'ACTIVE' && s.jenis !== 'HO' && (S.boot.all || S.boot.siteIds.indexOf(s.site_id) >= 0));
const siteOpts = () => scopeSites().map((s) => [s.site_id, s.kode_site]);
const yearOpts = () => { const y = +todayStr().slice(0, 4); return [y, y - 1]; };
const multiSite = () => scopeSites().length > 1;   // Admin Site / PJO satu site: pilihan site disembunyikan
function filterBar(id, fields, st, onChange, extra = '') {
  fields = fields.filter((f) => f.k !== 'site' || multiSite());
  return `<div class="card mb16" id="${id}"><div class="tbar">${fields.map((f) => `<div class="fld"><label>${esc(f.l)}</label><select class="sel sm" data-fk="${f.k}">${(f.all ? [['', f.all]] : []).concat(f.opts).map((o) => { const [v, l] = Array.isArray(o) ? o : [o, o]; return `<option value="${esc(v)}" ${String(st[f.k] || '') === String(v) ? 'selected' : ''}>${esc(l)}</option>`; }).join('')}</select></div>`).join('')}${extra}
    <div class="row" style="margin-left:auto"><button class="btn sm ghost" data-reset>${ic('restart_alt')}Reset</button></div></div></div>`;
}
function bindFilter(el, id, st, onChange, defaults) {
  $$(`#${id} [data-fk]`, el).forEach((s) => (s.onchange = () => { st[s.dataset.fk] = s.value; onChange(); }));
  const r = $(`#${id} [data-reset]`, el); if (r) r.onclick = () => { Object.keys(st).forEach((k) => delete st[k]); Object.assign(st, defaults); onChange(true); };
}
const hero = (title, sub, chips = []) => `<div class="hero"><div class="chips"><span class="hc">${ic('cloud_done', 's16')}Sinkron GAS: OK</span>${chips.map((c) => `<span class="hc ${c[1] || ''}">${esc(c[0])}</span>`).join('')}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p><div class="meta">${ic('schedule', 's16')}Update terakhir: ${tglJam(S.boot.serverTime)} WIB</div></div>`;
const insight = (items) => `<div class="insight"><h4>${ic('auto_awesome')}Insight otomatis</h4><ul>${items.filter(Boolean).map((x) => `<li>${x}</li>`).join('')}</ul></div>`;
function barCfg(labels, sets, opt = {}) {
  return { type: 'bar', data: { labels, datasets: sets.map((s) => Object.assign({ borderRadius: 4, maxBarThickness: 34 }, s)) }, plugins: [pctLabel],
    options: Object.assign({ plugins: { pctLabel: { on: opt.labels !== false } }, indexAxis: opt.horizontal ? 'y' : 'x', scales: { x: { grid: { display: !!opt.horizontal } }, y: { beginAtZero: true, grid: { color: Charts.css('--line') } } } }, opt.options || {}) };
}
/** Gauge setengah lingkaran (seperti speedometer); warna mengikuti ambang kepatuhan. */
const gaugeCfg = (pct) => { const v = clamp(Number(pct) || 0, 0, 100); const c = v >= 90 ? COL.ok : v >= 70 ? COL.warn : COL.bad;
  return { type: 'doughnut', data: { datasets: [{ data: [v, 100 - v], backgroundColor: [c, Charts.css('--line')], borderWidth: 0 }] }, options: { rotation: -90, circumference: 180, cutout: '74%', plugins: { legend: { display: false }, tooltip: { enabled: false } }, animation: { duration: 600 } } }; };
const donutCfg = (labels, data, colors, legendPos = 'right') => ({ type: 'doughnut', data: { labels, datasets: [{ data, backgroundColor: colors, borderWidth: 2, borderColor: Charts.css('--card') }] }, options: { cutout: '68%', plugins: { legend: { position: legendPos } } } });

