  const run = () => { LS.set('f:hoap', st); const pay = { tahun: +st.tahun, bulan: +st.bulan || 0, sites: st.site ? [st.site] : [] }; loadPage('hoapd:' + JSON.stringify(pay), 'dash.hoap', pay, draw, () => (el.innerHTML = skPage())); };
