/* ============================================================
   MODUL KERJA: RTP Terpadu, Audit SMKP/Management, Kelola Prosedur, MoM, Submit Laporan
   ============================================================ */
/** Jalankan aksi tombol dengan status sibuk + toast galat; kembalikan hasil atau null. */
async function busy(btn, fn) {
  if (btn && btn.classList.contains('is-busy')) return null; const html = btn ? btn.innerHTML : '';
  if (btn) { btn.classList.add('is-busy'); btn.innerHTML = '<span class="spin"></span> Memproses…'; }
  try { return await fn(); } catch (e) { toast(e.message, 'bad'); return null; } finally { if (btn && document.body.contains(btn)) { btn.classList.remove('is-busy'); btn.innerHTML = html; } }
}
/** Daftar karyawan aktif (dibatasi server sesuai cakupan site) untuk memilih PIC. */
async function usersPick(siteId) {
  const d = await Data.get('upick', 'user.list', {}, 120000);
  return d.rows.filter((u) => u.status === 'ACTIVE' && !/^EXT/.test(u.nrp) && (!siteId || u.site_id === siteId)).map((u) => [u.user_id, `${u.nama} — ${u.nrp} (${u.site || '-'})`]);
}
/** Dialog cari karyawan aktif dari site mana pun (nama / NRP). Mengembalikan user_id, atau null bila dibatalkan. */
async function empSearchDlg({ title, intro = '', ok = 'Pilih', skip = '', self = false }) {
  const d = await Data.get('upick', 'user.list', {}, 120000); const all = d.rows.filter((u) => u.status === 'ACTIVE' && !/^EXT/.test(u.nrp));
  return new Promise((res) => {
    let pick = null;
    const m = modal({ title: esc(title), body: `${intro ? `<div class="small sub mb12">${intro}</div>` : ''}<div class="fld"><label>Cari karyawan <span class="req">*</span></label><div class="inp-ic">${ic('search')}<input class="inp" id="eQ" placeholder="Ketik nama atau NRP…" autocomplete="off"></div><div class="list card mt8 hide" id="eL" style="max-height:220px;overflow:auto"></div><div id="eSel" class="mt8"></div></div>`,
      foot: `<button class="btn" data-x>Batal</button>${skip ? `<button class="btn" id="eSkip">${esc(skip)}</button>` : ''}${self ? `<button class="btn" id="eSelf">${ic('person')}Saya sendiri</button>` : ''}<button class="btn pri" id="eOk">${esc(ok)}</button>`, onClose: () => res(null) });
    m.$('#eQ').oninput = debounce(() => {
      const q = m.$('#eQ').value.trim().toLowerCase(); const L = m.$('#eL'); if (q.length < 2) { L.classList.add('hide'); return; }
      const hit = all.filter((u) => (u.nama + ' ' + u.nrp).toLowerCase().indexOf(q) >= 0).slice(0, 20); L.classList.remove('hide');
      L.innerHTML = hit.length ? hit.map((u) => `<button class="li" data-u="${esc(u.user_id)}" style="width:100%;text-align:left"><div class="grow"><div class="b">${esc(u.nama)}</div><div class="small sub">${esc(u.nrp)} · ${esc(u.jabatan || '-')} · ${esc(u.site || '-')}</div></div></button>`).join('') : '<div class="pad small sub">Tidak ada karyawan yang cocok.</div>';
      $$('[data-u]', L).forEach((x) => (x.onclick = () => { pick = all.find((u) => u.user_id === x.dataset.u); L.classList.add('hide'); m.$('#eQ').value = ''; m.$('#eSel').innerHTML = `<div class="card pad row"><div class="av sm lt">${esc(initials(pick.nama))}</div><div class="grow"><div class="b">${esc(pick.nama)}</div><div class="small sub">${esc(pick.nrp)} · ${esc(pick.site || '-')}</div></div></div>`; }));
    });
    m.$('#eOk').onclick = () => { if (!pick) return toast('Pilih karyawan terlebih dahulu.', 'warn'); res(pick.user_id); m.el.remove(); };
    const sf = m.$('#eSelf'); if (sf) sf.onclick = () => { res(S.user.user_id); m.el.remove(); };
    const sk = m.$('#eSkip'); if (sk) sk.onclick = () => { res(''); m.el.remove(); };
  });
}
const stepper = (steps, cur, v) => `<div class="stepper ${v ? 'v' : ''}">${steps.map((s, i) => `${i ? `<div class="st-ln ${i <= cur ? 'done' : ''}"></div>` : ''}<div class="st ${i < cur ? 'done' : i === cur ? 'cur' : ''}"><div class="c">${i < cur ? ic('check', 's16') : i + 1}</div><div class="t">${esc(s)}</div></div>`).join('')}</div>`;
const fileChip = (id, nama) => `<button class="chip" data-act="open-file" data-id="${esc(id || '')}" data-nama="${esc(nama || 'berkas')}">${ic(/\.pdf$/i.test(nama || '') ? 'picture_as_pdf' : /\.(png|jpe?g|webp)$/i.test(nama || '') ? 'image' : 'description', 's18')}${esc(nama || 'berkas')}</button>`;
/** Pilih & unggah satu/lebih berkas; kembalikan [{file_id,nama}] */
async function pickUpload(accept, meta, multiple = true, btn) {
  const fs = await pickFiles(accept, multiple); if (!fs.length) return [];
  const out = []; for (const f of fs) { const r = await busy(btn, () => uploadFile(f, meta)); if (r) out.push({ file_id: r.file_id, nama: r.nama }); }
  if (out.length) toast(`${out.length} berkas terunggah.`, 'ok'); return out;
}

