      chips: (rows) => [['Open', 'radio_button_unchecked'], ['In Progress', 'pending'], ['Overdue', 'alarm'], ['Submitted', 'upload'], ['Verified', 'verified'], ['Returned', 'undo'], ['Closed', 'check_circle']].map(([k, i]) => ({ k, l: k, icon: i, n: rows.filter((r) => r.eff === k).length })), chipFilter: (r, k) => r.eff === k,
