  const users = await usersPick().catch(() => []); let mode = 'site';
  const m = modal({ title: 'Tetapkan Wajib Baca — ' + esc(doc.nomor), size: 'lg', body: `<p class="sub mb16">${esc(doc.judul)} · <span class="mono">${esc(doc.rev)}</span></p>
    <div class="fld"><label>Cara menentukan sasaran</label><div class="seg" id="wbM">${[['site', 'Semua karyawan site'], ['rule', 'Berdasarkan jabatan / departemen'], ['list', 'Pilih karyawan']].map(([k, l]) => `<button data-m="${k}" class="${k === mode ? 'on' : ''}">${l}</button>`).join('')}</div></div>
    <div class="fgrid mt16"><div class="fld full"><label>Site</label><div class="row wrap" id="wbS">${siteOpts().map(([v, l]) => `<label class="chip ${siteOpts().length === 1 ? 'on' : ''}"><input type="checkbox" value="${v}" hidden ${siteOpts().length === 1 ? 'checked' : ''}>${esc(l)}</label>`).join('')}</div><div class="hint">Kosongkan untuk semua site dalam cakupan Anda.</div></div>
      <div class="fld rl"><label>Jabatan mengandung (pisahkan koma)</label><input class="inp" id="wbJ" placeholder="Operator, Driver, Mekanik"></div><div class="fld rl"><label>Departemen (pisahkan koma)</label><input class="inp" id="wbD" placeholder="Produksi, Plant"></div>
      <div class="fld rl"><label>Kategori</label><select class="sel" id="wbK"><option value="">Semua</option><option>Staff</option><option>Non-Staff</option></select></div>
      <div class="fld full ls hide"><label>Karyawan</label><select class="sel" id="wbU" multiple size="8">${users.map(([v, l]) => `<option value="${v}">${esc(l)}</option>`).join('')}</select><div class="hint">Tahan Ctrl / ⌘ untuk memilih lebih dari satu.</div></div>
      <div class="fld"><label>Batas waktu baca <span class="req">*</span></label><input class="inp" type="date" id="wbB" value="${addDaysStr(14)}" min="${todayStr()}"></div><div class="fld"><label>Revisi baru</label><label class="row"><span class="sw"><input type="checkbox" id="wbR" checked><i></i></span><span class="small sub">Wajib baca ulang saat ada revisi baru</span></label></div></div>
    <div class="fld mt16"><label>Pertanyaan 1 untuk karyawan <span class="hint">(opsional — pemahaman isi prosedur)</span></label><textarea class="ta" id="wbQ" maxlength="300" style="min-height:56px" placeholder="Kosongkan untuk pertanyaan standar"></textarea></div>
    <div class="note mt8">${ic('quiz')}<div>Karyawan wajib menjawab <b>4 pertanyaan isian</b> sebelum konfirmasi baca: (1) pemahaman, (2) ketersampaian / kejelasan, (3) bagian yang kurang jelas atau sulit, (4) <b>saran dan masukan</b>. Tidak ada pilihan ganda dan tidak ada benar/salah.</div></div>
    <div class="note info mt16" id="wbN">${ic('groups')}<div>Menghitung sasaran…</div></div>`, foot: `<button class="btn" data-x>Batal</button><button class="btn pri" id="wbOk">${ic('fact_check')}Tetapkan</button>` });
  const rule = () => { const sites = $$('#wbS input:checked', m.el).map((x) => x.value); const sp = (v) => v.split(',').map((x) => x.trim()).filter(Boolean); return mode === 'list' ? { mode, users: $$('#wbU option:checked', m.el).map((o) => o.value), sites } : mode === 'rule' ? { mode, sites, jabatan: sp(m.$('#wbJ').value), departemen: sp(m.$('#wbD').value), kategori: m.$('#wbK').value ? [m.$('#wbK').value] : [] } : { mode, sites }; };
  const prev = debounce(async () => { try { const r = await API.run('doc.wajibPreview', { rule: rule() }); m.$('#wbN').innerHTML = `${ic('groups')}<div><b class="num">${fmtN(r.n)}</b> karyawan akan menerima tugas wajib baca dan notifikasi.</div>`; } catch (e) { m.$('#wbN').innerHTML = `${ic('error')}<div>${esc(e.message)}</div>`; } }, 350);
  const paint = () => { $$('.rl', m.el).forEach((x) => x.classList.toggle('hide', mode !== 'rule')); $$('.ls', m.el).forEach((x) => x.classList.toggle('hide', mode !== 'list')); $$('#wbM button', m.el).forEach((b) => b.classList.toggle('on', b.dataset.m === mode)); prev(); };
  $$('#wbM button', m.el).forEach((b) => (b.onclick = () => { mode = b.dataset.m; paint(); })); m.el.addEventListener('input', prev); m.el.addEventListener('change', prev); m.el.addEventListener('click', (e) => { if (e.target.closest('label.chip')) setTimeout(prev, 0); }); paint();
