/* ── W-27 Form pengajuan dokumen / revisi (dengan pemilihan Reviewer & Approver) ── */
const DOC_FLOW = ['Pengaju', 'Review', 'Approval', 'Aktif'];
P['doc-form'] = async (el, p) => {
  let base = {}; let file = null; el.innerHTML = skPage();
  try {
    if (p.id || p.revisi) { const d = await API.run('doc.get', { id: p.id || p.revisi }); base = d.doc; base.reviewers = (d.reviewers || []).map((x) => x.user_id); if (p.id && d.doc.status !== 'DRAFT') { toast('Dokumen ini sedang diproses; buka lewat halaman review.', 'warn'); return go('doc-review', { id: p.id }); } if (p.revisi) { const n = +(String(base.rev).match(/\d+/) || [0])[0] + 1; base = Object.assign({}, base, { rev: 'Rev.' + n, file_id: '', file_nama: '', alasan: '', reviewers: [], approver_id: '', catatan: '' }); } }
  } catch (e) { el.innerHTML = errorState(e); return; }
  let C; try { C = await API.run('doc.candidates', { level: base.level || '', site_id: base.site_id || '' }); } catch (e) { el.innerHTML = ph('Ajukan Dokumen', '', '', 'Kembali') + `<div class="note info">${ic('info')}<div>${esc(e.message)} Pengajuan dokumen dilakukan oleh karyawan Head Office, Admin Site, atau Admin Departemen.</div></div>`; return; }
  let level = base.level || C.level, site = base.site_id || C.site; let rvs = (base.reviewers && base.reviewers.length ? base.reviewers : (base.reviewer_id ? [base.reviewer_id] : [''])).slice(); let ap = base.approver_id || ''; const manual = !!p.revisi || (!!base.nomor && !!p.id && !base.pemilik);
  const jenisOpt = C.jenis.map((j) => `<option ${j === (base.jenis || 'Prosedur') ? 'selected' : ''}>${esc(j)}</option>`).join('');
  el.innerHTML = ph(p.revisi ? 'Ajukan Revisi Dokumen' : p.id ? 'Ubah Draft Dokumen' : 'Ajukan Dokumen Baru', 'Dokumen berlaku setelah disetujui Reviewer lalu Approver. Versi lama otomatis menjadi Superseded.', '', 'Kembali') +
    (base.catatan ? `<div class="note warn mb16">${ic('undo')}<div><b>Dikembalikan</b> — ${esc(base.catatan)}</div></div>` : '') +
    `<div class="grid g-65"><div class="card pad"><div class="fgrid">
      <div class="fld"><label>Level dokumen <span class="req">*</span></label><select class="sel" id="dLv" ${p.revisi ? 'disabled' : ''}>${C.canCorp ? `<option value="Corporate" ${level === 'Corporate' ? 'selected' : ''}>Corporate</option>` : ''}${C.canSite ? `<option value="Site" ${level === 'Site' ? 'selected' : ''}>Site</option>` : ''}</select></div>
      <div class="fld" id="dSiteW"><label>Site <span class="req">*</span></label><select class="sel" id="dSite" ${p.revisi ? 'disabled' : ''}>${C.sites.map(([v, l]) => `<option value="${v}" ${v === site ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></div>
      <div class="fld"><label>Jenis dokumen <span class="req">*</span></label><select class="sel" id="dJenis" ${p.revisi ? 'disabled' : ''}>${jenisOpt}</select></div>
      <div class="fld"><label>Pemilik proses (departemen) <span class="req">*</span></label><select class="sel" id="dPem" ${p.revisi ? 'disabled' : ''}><option value="">Pilih departemen…</option>${C.depts.map((d) => `<option value="${d.kode}" ${d.kode === base.pemilik ? 'selected' : ''}>${esc(d.kode)} — ${esc(d.nama)}</option>`).join('')}</select></div>
      <div class="fld"><label>Nomor dokumen</label><input class="inp mono" id="dNo" value="${esc(base.nomor || '')}" readonly><div class="hint" id="dNoH"></div></div>
      <div class="fld"><label>Revisi <span class="req">*</span></label><input class="inp" id="dRev" value="${esc(base.rev || 'Rev.0')}"></div>
      <div class="fld full"><label class="row"><span class="sw"><input type="checkbox" id="dMan" ${manual ? 'checked' : ''} ${p.revisi ? 'disabled' : ''}><i></i></span><span class="small sub">Pakai nomor yang sudah ada (dokumen lama HMSI / migrasi)</span></label></div>
      <div class="fld full"><label>Judul <span class="req">*</span></label><input class="inp" id="dJudul" value="${esc(base.judul || '')}"></div>
      <div class="fld full"><label>${p.revisi ? 'Alasan revisi *' : 'Catatan pengajuan'}</label><textarea class="ta" id="dAlasan">${esc(base.alasan || '')}</textarea></div></div>
      <div class="fld mt16"><label>Berkas dokumen (PDF / Word) <span class="req">*</span></label><div class="drop" id="dUp">${ic('upload_file', 's24')}<div class="b mt8" id="dUpT">${base.file_nama ? esc(base.file_nama) : 'Klik untuk memilih berkas'}</div><div class="small sub">PDF, DOC, DOCX · maks. ${S.boot.config.upload_pdf_mb} MB</div></div></div></div>
      <div class="col gap16"><div class="card pad"><div class="eyebrow">Alur persetujuan</div><div class="mt12" id="dFlow"></div>
        <div class="fld mt16"><label>Reviewer <span class="req">*</span></label><div id="rvBox" class="col gap8"></div><div class="hint" id="rvH"></div></div>
        <div class="fld mt12"><label>Approver (persetujuan akhir) <span class="req">*</span></label><select class="sel" id="apSel"></select><div class="hint" id="apH"></div></div><div id="flowNote" class="mt12"></div></div>
        <div class="note info" id="ruleN"></div></div></div>
    <div class="sticky-bar"><button class="btn" id="dDraft">${ic('save')}Simpan draft</button><button class="btn pri grow" id="dSub">${ic('send')}Ajukan ke Reviewer</button></div>`;
  const $d = (id) => $('#' + id, el); let pool = C.pool; let maxR = C.maxReviewer;
  const noPrev = debounce(async () => {
    if (!$d('dMan')) return; const man = $d('dMan').checked; $d('dNo').readOnly = !man || !!p.revisi; if (p.revisi) { $d('dNoH').textContent = 'Nomor tetap pada revisi; hanya Rev yang naik.'; return; }
    if (man) { $d('dNoH').textContent = 'Ketik nomor dokumen yang sudah ada.'; return; }
    if (!$d('dPem').value) { $d('dNo').value = ''; $d('dNoH').textContent = 'Pilih departemen pemilik proses untuk membuat nomor otomatis.'; return; }
    try { const r = await API.run('doc.nextNo', { jenis: $d('dJenis').value, pemilik: $d('dPem').value }); $d('dNo').value = r.nomor; $d('dNoH').textContent = 'Nomor dibuat otomatis (Level ' + r.level + ').'; } catch (e) { $d('dNoH').textContent = e.message; }
  }, 200);
  const paintFlow = () => {
    const corp = level === 'Corporate'; const steps = ['Pengaju'].concat(rvs.map((_, i) => 'Review' + (rvs.length > 1 ? ' ' + (i + 1) : ''))).concat(['Approval', 'Aktif']); $d('dFlow').innerHTML = stepper(steps, 0, true);
    const opt = (cur, taken) => '<option value="">Pilih reviewer…</option>' + pool.reviewers.filter((x) => x.user_id === cur || taken.indexOf(x.user_id) < 0).map((x) => `<option value="${x.user_id}" ${x.user_id === cur ? 'selected' : ''}>${esc(x.nama)} — ${esc(x.jabatan || '')} (${esc(x.nrp)})</option>`).join('');
    $d('rvBox').innerHTML = rvs.map((v, i) => `<div class="row gap8"><select class="sel grow" data-rv="${i}">${opt(v, rvs.concat([ap]))}</select>${rvs.length > 1 ? `<button class="btn sm ghost icon" data-rm="${i}" aria-label="Hapus reviewer">${ic('close')}</button>` : ''}</div>`).join('') + (rvs.length < maxR ? `<button class="btn sm" id="rvAdd" style="align-self:flex-start">${ic('add')}Tambah tahap review</button>` : '');
    $d('rvH').textContent = corp ? 'Corporate: bisa lebih dari satu reviewer, berurutan (maks. ' + maxR + '). Semua karyawan Head Office dapat ditunjuk.' : 'Site: minimal 1 reviewer dari karyawan Staff site ini. Reviewer tambahan bersifat opsional (maks. ' + maxR + ').';
    $d('apSel').innerHTML = '<option value="">' + (pool.approvers.length ? 'Pilih approver…' : 'Belum ada') + '</option>' + pool.approvers.filter((x) => rvs.indexOf(x.user_id) < 0).map((x) => `<option value="${x.user_id}" ${x.user_id === ap ? 'selected' : ''}>${esc(x.nama)} — ${esc(x.jabatan || '')}</option>`).join('');
    $d('apH').textContent = corp ? 'Approver dokumen Corporate: President Direktur.' : 'Approver dokumen site: PJO site ini (wajib).';
    $d('flowNote').innerHTML = !pool.approvers.length ? `<div class="note warn">${ic('warning')}<div>${corp ? 'Belum ada <b>President Direktur</b>. Minta SHEC Corporate menunjuknya di Penunjukan Peran.' : 'Site ini belum punya <b>PJO</b>. Minta SHEC Corporate menunjuk PJO.'}</div></div>` : !pool.reviewers.length ? `<div class="note warn">${ic('warning')}<div>Belum ada kandidat reviewer.</div></div>` : '';
    $d('ruleN').innerHTML = ic('policy') + `<div>${corp ? 'Dokumen Corporate: karyawan Head Office dapat mengajukan, direview bertahap, lalu disetujui <b>President Direktur</b>.' : 'Dokumen site: diajukan Admin Site / Admin Departemen (sesuai departemennya), direview 1 staff (reviewer tambahan opsional), disetujui <b>PJO</b>.'} Pengaju tidak dapat meninjau atau menyetujui dokumennya sendiri.</div>`;
    $$('[data-rv]', el).forEach((x) => (x.onchange = () => { rvs[+x.dataset.rv] = x.value; paintFlow(); })); $$('[data-rm]', el).forEach((b) => (b.onclick = () => { rvs.splice(+b.dataset.rm, 1); paintFlow(); })); const ad = $d('rvAdd'); if (ad) ad.onclick = () => { rvs.push(''); paintFlow(); }; $d('apSel').onchange = (e) => { ap = e.target.value; paintFlow(); };
  };
  const reload = async () => {
    level = $d('dLv').value; site = $d('dSite').value; $d('dSiteW').classList.toggle('hide', level === 'Corporate');
    try { const r = await Data.get('dcand:' + level + site, 'doc.candidates', { level, site_id: site }, 30000); pool = r.pool; maxR = r.maxReviewer; const cp = $d('dPem').value; $d('dPem').innerHTML = '<option value="">Pilih departemen…</option>' + r.depts.map((d) => `<option value="${d.kode}" ${d.kode === cp ? 'selected' : ''}>${esc(d.kode)} — ${esc(d.nama)}</option>`).join(''); } catch (e) { toast(e.message, 'bad'); }
    rvs = rvs.filter((id) => !id || pool.reviewers.some((x) => x.user_id === id)); if (!rvs.length) rvs = ['']; if (level === 'Site') rvs = rvs.slice(0, 1); if (ap && !pool.approvers.some((x) => x.user_id === ap)) ap = ''; if (!ap && pool.approvers.length === 1) ap = pool.approvers[0].user_id;
    paintFlow(); noPrev();
  };
  $d('dLv').onchange = reload; $d('dSite').onchange = reload; $d('dJenis').onchange = noPrev; $d('dPem').onchange = noPrev; $d('dMan').onchange = noPrev;
  if (!ap && pool.approvers.length === 1) ap = pool.approvers[0].user_id; $d('dSiteW').classList.toggle('hide', level === 'Corporate'); paintFlow(); noPrev();
  $d('dUp').onclick = async () => { const fs = await pickUpload('application/pdf,.doc,.docx', { modul: 'dokumen', site_id: level === 'Site' ? site : S.user.site_id }, false); if (fs[0]) { file = fs[0]; $d('dUpT').textContent = file.nama; } };
  const save = async (submit, btn) => {
    const v = { id: p.id || '', level, site_id: level === 'Site' ? site : '', jenis: $d('dJenis').value, pemilik: $d('dPem').value, nomor: $d('dNo').value.trim(), nomor_manual: $d('dMan').checked || !!p.revisi, rev: $d('dRev').value.trim() || 'Rev.0', judul: $d('dJudul').value.trim(), alasan: $d('dAlasan').value.trim(), reviewers: rvs.filter(Boolean), approver_id: ap, submit,
      file_id: file ? file.file_id : base.file_id || '', file_nama: file ? file.nama : base.file_nama || '' };
    if (p.revisi) v.nomor = base.nomor;
    if (!v.judul) return toast('Judul wajib diisi.', 'warn'); if (!v.pemilik) return toast('Pilih departemen pemilik proses.', 'warn'); if (p.revisi && !v.alasan) return toast('Isi alasan revisi.', 'warn');
    if (submit) { if (!v.file_id) return toast('Unggah berkas dokumen terlebih dahulu.', 'warn'); if (!v.reviewers.length) return toast('Pilih minimal satu Reviewer.', 'warn'); if (!ap) return toast(level === 'Corporate' ? 'Approver (President Direktur) belum dipilih.' : 'Pilih PJO sebagai Approver.', 'warn'); }
    const r = await busy(btn, () => API.run('doc.request', v, uid()));
    if (r) { Data.drop('docm'); Data.drop('tasks'); Data.drop('home'); toast(submit ? 'Diajukan — notifikasi dikirim ke Reviewer.' : 'Draft tersimpan.', 'ok'); go('prosedur-kelola'); }
  };
  $d('dDraft').onclick = (e) => save(false, e.currentTarget); $d('dSub').onclick = (e) => save(true, e.currentTarget);
};

/* ── W-28 Review & persetujuan dokumen (tahap Reviewer → Approver) ── */
P['doc-review'] = async (el, p) => {
  const key = 'docr:' + p.id;
  const draw = (d) => {
    const x = d.doc; const nR = Math.max(1, (d.reviewers || []).length); const steps = ['Pengaju'].concat(Array.from({ length: nR }, (_, i) => 'Review' + (nR > 1 ? ' ' + (i + 1) : ''))).concat(['Approval', 'Aktif']); const ri = (d.reviewers || []).findIndex((r) => r.aktif); const cur = { DRAFT: 0, IN_REVIEW: 1 + Math.max(0, ri), IN_APPROVAL: 1 + nR, ACTIVE: steps.length, SUPERSEDED: steps.length }[x.status] || 0; const stg = x.status === 'IN_REVIEW' ? 'review' : 'approval';
    const aksiLbl = x.status === 'IN_REVIEW' ? 'Setujui & teruskan ke Approver' : 'Setujui & berlakukan';
    el.innerHTML = ph(x.nomor + ' · ' + x.rev, x.judul, d.canWithdraw ? `<button class="btn" id="dWd">${ic('undo')}Tarik kembali ke draft</button>` : '', 'Kembali') +
      `<div class="card pad mb16"><div class="row wrap between"><div class="row wrap">${pill(x.status)}<span class="pill outline lc">${esc(x.jenis)}</span><span class="pill outline lc">${esc(x.level)}</span>${x.file_nama ? '' : '<span class="pill warn">Belum ada berkas</span>'}</div><div class="small sub">Diajukan oleh <b>${esc(d.pemohon || '-')}</b></div></div><div class="mt16">${stepper(steps, cur)}</div></div>
      <div class="split"><div class="lft"><div class="row between" style="color:#cbd5e1"><span class="mono">${esc(x.file_nama || 'Belum ada berkas')}</span><button class="btn sm" data-act="open-file" data-id="${esc(x.file_id)}" data-nama="${esc(x.file_nama || x.nomor + '.pdf')}">${ic('open_in_full')}Buka dokumen</button></div><div class="center col" style="flex:1;align-items:center;justify-content:center;color:#94a3b8">${ic('description', 's48')}<div class="mt8">Klik "Buka dokumen" untuk membaca isi sebelum memutuskan.</div></div></div>
      <div class="rgt"><div><div class="eyebrow">Alur & penanggung jawab</div><div class="list mt8">${[['Pengaju', d.pemohon, 'edit_note', x.status !== 'DRAFT', false]].concat((d.reviewers && d.reviewers.length ? d.reviewers : [{ nama: d.reviewerNama, selesai: ['IN_APPROVAL', 'ACTIVE', 'SUPERSEDED'].indexOf(x.status) >= 0, aktif: x.status === 'IN_REVIEW' }]).map((r, i, a) => ['Reviewer' + (a.length > 1 ? ' ' + (i + 1) : ''), r.nama || 'Reviewer', 'rate_review', r.selesai, r.aktif])).concat([['Approver', d.approverNama || '—', 'approval', ['ACTIVE', 'SUPERSEDED'].indexOf(x.status) >= 0, x.status === 'IN_APPROVAL']]).map(([r, nm, i, done, act]) => `<div class="li"><div class="lic">${ic(i)}</div><div class="grow"><div class="small sub">${r}</div><div class="b">${esc(nm || 'Belum dipilih')}</div></div>${done ? pill('SUDAH', 'Selesai') : act ? pill('Submitted', 'Menunggu') : ''}</div>`).join('')}</div></div>
        ${esignCard(d)}
        ${x.alasan ? `<div><div class="eyebrow">Catatan pengaju</div><p class="mt4">${esc(x.alasan)}</p></div>` : ''}
        <div><div class="eyebrow">Riwayat</div><div class="timeline mt8">${d.riwayat.length ? d.riwayat.slice().reverse().map((h) => `<div class="tl-i"><div class="b">${esc(h.aksi)}</div><div class="small sub">${esc(h.nama)} · ${tglJam(h.at)}</div>${h.catatan ? `<div class="note warn mt8">${ic('chat')}<div>${esc(h.catatan)}</div></div>` : ''}</div>`).join('') : '<div class="small sub">Belum ada riwayat.</div>'}</div></div>
        ${d.canReview ? `<div class="card pad" style="border:2px solid var(--orange)"><div class="b mb8">${stg === 'review' ? 'Keputusan Anda sebagai Reviewer' : 'Keputusan Anda sebagai Approver'}</div><div class="fld"><label>Catatan ${stg === 'review' ? '(opsional bila disetujui)' : '(opsional)'} · <b>wajib</b> bila dikembalikan</label><textarea class="ta" id="rvN"></textarea></div><div class="row mt12"><button class="btn odanger grow" id="rvNo">${ic('undo')}Kembalikan ke pengaju</button><button class="btn pri grow" id="rvOk">${ic('task_alt')}${aksiLbl}</button></div></div>` : (['IN_REVIEW', 'IN_APPROVAL'].indexOf(x.status) >= 0 ? `<div class="note info">${ic('hourglass_top')}<div>Menunggu ${stg === 'review' ? 'review dari <b>' + esc(d.reviewerNama || 'Reviewer') + '</b>' : 'persetujuan dari <b>' + esc(d.approverNama || 'Approver') + '</b>'}.</div></div>` : x.status === 'DRAFT' && x.catatan ? `<div class="note warn">${ic('undo')}<div><b>Dikembalikan:</b> ${esc(x.catatan)}</div></div>` : '')}
      </div></div>`;
    const dec = async (decision, btn) => { const note = $('#rvN').value.trim(); if (decision !== 'approve' && !note) return toast('Tuliskan alasan pengembalian.', 'warn'); let pin = ''; if (decision === 'approve') { pin = await esignAskPin((x.nomor || '') + ' ' + (x.rev || '') + ' - ' + (x.judul || '')); if (!pin) return; } const r = await busy(btn, () => API.run('doc.review', { id: x.doc_id, decision, note, pin }, uid())); if (r) { Data.drop('docm'); Data.drop('docs'); Data.drop('tasks'); Data.drop('home'); Data.drop(key); toast(decision !== 'approve' ? 'Dokumen dikembalikan ke pengaju.' : r.status === 'IN_APPROVAL' ? 'Review disetujui — diteruskan ke Approver.' : 'Dokumen disetujui & berlaku.', 'ok');
      if (decision === 'approve' && r.status === 'ACTIVE') { const bar = toast('Menerbitkan PDF dokumen…', 'info'); try { const pr = await esignPublish(x.doc_id); toast('PDF terbit: ' + pr.nama, 'ok'); } catch (er) { toast('Dokumen sudah berlaku, tetapi PDF belum terbit: ' + er.message + ' Buka detail dokumen lalu pilih Terbitkan PDF.', 'warn'); } Data.drop('docm'); Data.drop('docs'); }
      go('prosedur-kelola'); } };
    esignBind(el, d);
    const ok = $('#rvOk'); if (ok) { ok.onclick = () => dec('approve', ok); $('#rvNo').onclick = (e) => dec('return', e.currentTarget); }
    const wd = $('#dWd'); if (wd) wd.onclick = async () => { if (!(await confirmDlg({ title: 'Tarik pengajuan?', msg: 'Dokumen kembali ke draft dan Anda dapat mengubahnya sebelum mengajukan ulang.', ok: 'Tarik' }))) return; if (await busy(wd, () => API.run('doc.withdraw', { id: x.doc_id }, uid()))) { Data.drop('docm'); Data.drop(key); Data.drop('tasks'); toast('Dokumen ditarik ke draft.', 'ok'); go('doc-form', { id: x.doc_id }); } };
  };
  loadPage(key, 'doc.get', { id: p.id }, draw, () => (el.innerHTML = skPage()));
};

/* ── W-29 / W-30 MoM Meeting ── */
