    const bkLoad = async () => { const b = $('#bkCard'); if (!b) return; try { const r = await API.run('backup.info', {}); b.innerHTML = `<div class="row between wrap"><div><div class="b">Status cadangan database</div><div class="small sub">Terakhir: ${r.terakhir ? esc(r.terakhir) : 'belum pernah'}${r.jumlah >= 0 ? ' · ' + r.jumlah + ' salinan tersimpan' : ''}</div><div class="small ${/^GAGAL/.test(r.status) ? 'b' : 'sub'}" style="${/^GAGAL/.test(r.status) ? 'color:var(--bad)' : ''}">${esc(r.status || '')}</div></div><button class="btn" id="bkRun">${ic('backup')}Cadangkan sekarang</button></div>`; $('#bkRun').onclick = async (e) => { const x = await busy(e.currentTarget, () => API.run('backup.run', {}, uid())); if (x) { toast('Cadangan dibuat: ' + x.nama, 'ok'); bkLoad(); } }; } catch (er) { b.innerHTML = '<div class="small sub">Status cadangan tidak dapat dimuat.</div>'; } };
