  const count = debounce(async () => { try { const r = await API.run('info.preview', { sasaran: sas() }); const n = $('#iN'); if (n) n.innerHTML = `${ic('groups')}<div><b class="num">${fmtN(r.n)}</b> karyawan akan menerima pengumuman ini.</div>`; } catch (e) { const n = $('#iN'); if (n) n.innerHTML = `${ic('error')}<div>${esc(e.message)}</div>`; } }, 350);
  const preview = () => { const pv = $('#iPv'); if (!pv) return; pv.innerHTML = posterHtml({ info_id: '', jenis: f.jenis, judul: f.judul || 'Judul pengumuman', prioritas: f.prioritas, wajib: f.wajib, konfirmasi: false, selesai: f.tayang_selesai, lampiran: f.lampiran }) + (f.ringkasan ? `<div class="card pad mt8 small">${esc(f.ringkasan)}</div>` : ''); const im = $('img[data-img]', pv); if (im && local[im.dataset.img]) { im.src = local[im.dataset.img]; im.removeAttribute('data-img'); } hydrateImgs(pv); $('.poster', pv).removeAttribute('data-go'); };
