/* ── Target HOAP per personel (Admin Site / SHEC) ── */
P['hoap-target'] = async (el) => {
  let site = S.user.site_id; const multi = has('CORPORATE'); let ym = todayStr().slice(0, 7); const sel = new Set(); let jb = '';
  const months = [-2, -1, 0, 1].map((k) => { const d = new Date(Date.UTC(+ym.slice(0, 4), +ym.slice(5, 7) - 1 + k, 1)); return d.toISOString().slice(0, 7); });
  const load = async () => { const d = await API.run('hoap.target.list', { site_id: site, ym }); draw(d); };
  const draw = (d) => {
    const list = d.rows.filter((r) => !jb || r.jabatan === jb);
    el.innerHTML = ph('Target HOAP Personel', 'Atur target tiap personel menurut level jabatan. Penyesuaian karena business trip, sakit panjang, atau cuti dapat dibatasi untuk satu bulan dan wajib beralasan.', '') +
      `<div class="card pad mb16"><div class="fgrid">${multi ? `<div class="fld"><label>Site</label><select class="sel" id="tgS">${siteOpts().map(([v, l]) => `<option value="${v}" ${v === site ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></div>` : ''}<div class="fld"><label>Bulan</label><select class="sel" id="tgM">${months.map((m) => `<option value="${m}" ${m === ym ? 'selected' : ''}>${ymLabel(m)}</option>`).join('')}</select></div><div class="fld"><label>Jabatan</label><select class="sel" id="tgJ"><option value="">Semua jabatan</option>${uniq(d.rows.map((r) => r.jabatan)).sort().map((j) => `<option ${jb === j ? 'selected' : ''}>${esc(j)}</option>`).join('')}</select></div></div>
        <div class="row wrap gap8 mt12"><button class="btn pri" id="tgA" ${sel.size ? '' : 'disabled'}>${ic('tune')}Atur target (${sel.size} terpilih)</button><button class="btn" id="tgR" ${sel.size ? '' : 'disabled'}>${ic('restart_alt')}Kembalikan ke standar</button><button class="btn ghost" id="tgAll">${ic('select_all')}Pilih semua yang tampil</button><button class="btn ghost" id="tgNone">Kosongkan pilihan</button></div></div><div id="tgT"></div>`;
    const cell = (c) => `<span class="num b" style="${c.src !== 'standar' ? 'color:var(--orange)' : ''}" title="${c.src === 'standar' ? 'Standar' : (c.src === 'bulan' ? 'Penyesuaian bulan ini' : 'Target tetap') + (c.alasan ? ' — ' + c.alasan : '')}">${c.eff}</span>${c.src !== 'standar' ? ` <span class="small sub">(std ${c.standar})</span>` : ''}`;
    TableView($('#tgT'), { rows: list, pageSize: 25, search: (r) => r.nama + ' ' + r.nrp + ' ' + r.jabatan, searchPh: 'Cari nama / NRP / jabatan…', exportName: 'Target_HOAP',
      cols: [{ k: 'sel', l: '', nosort: true, noexp: true, x: (r) => `<input type="checkbox" data-s="${r.user_id}" ${sel.has(r.user_id) ? 'checked' : ''} aria-label="Pilih ${esc(r.nama)}">` }, { k: 'nama', l: 'Karyawan', x: (r) => `<b>${esc(r.nama)}</b><div class="small sub mono">${esc(r.nrp)}</div>` }, { k: 'jabatan', l: 'Jabatan', x: (r) => `${esc(r.jabatan || '')}<div class="small sub">${esc(r.kategori)}</div>` }]
        .concat(d.programs.map((p) => ({ k: 'p' + p, l: p, cls: 'num', x: (r) => cell(r.t[p]), csv: (r) => r.t[p].eff, sort: (r) => r.t[p].eff }))).concat([{ k: 'x', l: '', nosort: true, noexp: true, x: (r) => `<button class="btn sm ghost icon" data-e="${r.user_id}" aria-label="Ubah target ${esc(r.nama)}">${ic('edit', 's18')}</button>` }]),
      after: (box) => { $$('[data-s]', box).forEach((c) => (c.onchange = () => { if (c.checked) sel.add(c.dataset.s); else sel.delete(c.dataset.s); $('#tgA').disabled = $('#tgR').disabled = !sel.size; $('#tgA').lastChild.textContent = `Atur target (${sel.size} terpilih)`; })); $$('[data-e]', box).forEach((b) => (b.onclick = () => dlg([b.dataset.e], d))); } });
    const s = $('#tgS'); if (s) s.onchange = () => { site = s.value; sel.clear(); load(); }; $('#tgM').onchange = (e) => { ym = e.target.value; load(); }; $('#tgJ').onchange = (e) => { jb = e.target.value; draw(d); };
    $('#tgAll').onclick = () => { list.forEach((r) => sel.add(r.user_id)); draw(d); }; $('#tgNone').onclick = () => { sel.clear(); draw(d); };
    $('#tgA').onclick = () => dlg([...sel], d);
    $('#tgR').onclick = async (e) => { if (!(await confirmDlg({ title: 'Kembalikan ke target standar?', msg: `${sel.size} karyawan: penyesuaian bulan ${ymLabel(ym)} dan target tetap dihapus dari perhitungan (kembali ke standar kategori).`, ok: 'Kembalikan' }))) return; const r = await busy(e.currentTarget, async () => { await API.run('hoap.target.set', { user_ids: [...sel], targets: Object.fromEntries(d.programs.map((p) => [p, 0])), mode: 'bulan', ym, reset: true }, uid()); return API.run('hoap.target.set', { user_ids: [...sel], targets: Object.fromEntries(d.programs.map((p) => [p, 0])), mode: 'tetap', reset: true }, uid()); }); if (r) { toast('Target dikembalikan ke standar.', 'ok'); Data.drop('hoap'); load(); } };
  };
  const dlg = (ids, d) => {
    const one = ids.length === 1 ? d.rows.find((r) => r.user_id === ids[0]) : null;
    formDlg({ title: one ? 'Target ' + one.nama : `Atur target ${ids.length} karyawan`, size: 'lg', ok: 'Simpan target', intro: `<p class="sub mb16">Kosongkan kolom program yang tidak diubah. ${one ? 'Standar: ' + d.programs.map((p) => p + ' ' + one.t[p].standar).join(' · ') : 'Nilai berlaku sama untuk semua karyawan terpilih.'}</p>`,
      fields: d.programs.map((p) => ({ k: 'p_' + p.replace(/\s/g, ''), l: 'Target ' + p, t: 'number', min: 0, max: 30, def: '' })).concat([{ k: 'mode', l: 'Berlaku', t: 'select', opts: [['bulan', 'Bulan ' + ymLabel(ym) + ' saja (penyesuaian)'], ['tetap', 'Seterusnya (target tetap level jabatan)']], def: 'bulan' }, { k: 'alasan', l: 'Alasan', t: 'select', opts: d.alasan, ph: 'Pilih alasan…', hint: 'Wajib untuk penyesuaian satu bulan atau bila target diturunkan dari standar.' }, { k: 'ket', l: 'Keterangan tambahan (opsional)', t: 'textarea', full: true, max: 150 }]),
      onSubmit: async (v) => { const targets = {}; d.programs.forEach((p) => { const x = v['p_' + p.replace(/\s/g, '')]; if (x !== '' && x !== undefined) targets[p] = x; }); if (!Object.keys(targets).length) throw new Error('Isi target minimal satu program.'); const r = await API.run('hoap.target.set', { user_ids: ids, targets, mode: v.mode, ym, alasan: [v.alasan, v.ket].filter(Boolean).join(' — ') }, uid()); toast(`Target ${r.karyawan} karyawan disimpan.`, 'ok'); Data.drop('hoap'); sel.clear(); load(); } });
  };
  el.innerHTML = skPage(); load().catch((e) => (el.innerHTML = errorState(e)));
};

