const XL_PRG = { 'Hazard Report': 'FFFFE6D5', 'HOT 5': 'FFEEE6FF', Inspeksi: 'FFE8F5E9' };
const xlFill = (argb) => ({ type: 'pattern', pattern: 'solid', fgColor: { argb } });
const xlBorder = { top: { style: 'thin', color: { argb: 'FFE5E7EB' } }, bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } }, left: { style: 'thin', color: { argb: 'FFE5E7EB' } }, right: { style: 'thin', color: { argb: 'FFE5E7EB' } } };
const xlDate = (s) => (s ? new Date(s.slice(0, 10) + 'T05:00:00Z') : '');
function xlCell(c, v, o = {}) { c.value = v; c.font = { name: 'Arial', size: o.sz || 9, bold: !!o.b, color: { argb: o.color || XL.ink } }; if (o.fill) c.fill = xlFill(o.fill); c.alignment = { vertical: 'middle', horizontal: o.h || 'left', wrapText: o.wrap !== false }; if (o.nf) c.numFmt = o.nf; if (o.border) c.border = xlBorder; return c; }
