  [['A', 'B', 'SITE', x.site], ['C', 'D', 'SITE CODE', kode], ['E', 'F', 'PERIODE', per], ['G', 'H', 'DIEKSPOR', when], ['I', 'J', 'FILTER', x.filter.replace(/ • PIC: Semua PIC/, '')]].forEach(([a, b, l, v]) => { xlMerge(s1, `${a}4:${b}4`, l, { b: 1, color: XL.gray, fill: XL.stripe }); xlMerge(s1, `${a}5:${b}5`, v, { sz: 10, b: 1 }); });
