  const ctl = (k) => $('#f_' + k, el); const got = (id) => $$(`#${id} input:checked`, el).map((i) => i.value);
  ctl('site_id').onchange = async (e) => { site = e.target.value; try { meta = await API.run('acc.meta', { site_id: site }); } catch (er) { return toast(er.message, 'bad'); } kar = meta.karyawan || []; ctl('korban_user_id').innerHTML = '<option value="">— bukan karyawan terdaftar / isi manual —</option>' + kar.map((u) => `<option value="${esc(u.user_id)}">${esc(u.nama + ' · ' + u.nrp)}</option>`).join(''); ctl('lokasi').innerHTML = '<option value="">Pilih lokasi</option>' + uniq(T.lokasi.concat(meta.lokasi || [])).map((x) => `<option>${esc(x)}</option>`).join(''); };
