/* ══ Dashboard APD & Safety Devices ══ */
const APD_KCOL = { 'Baju Kerja': '#475569', 'Topi Pelindung': '#CA8A04', 'Jas Hujan': '#0EA5E9', 'Sarung Tangan Kimia': '#9333EA', 'Sepatu Karet': '#1E293B', 'Ear Muff': '#BE123C', Helm: '#F26522', Sepatu: '#121A24', Kacamata: '#2F6FDB', Masker: '#0D9488', Rompi: '#F59E0B', 'Sarung Tangan': '#7C3AED', 'Pelindung Telinga': '#E11D48', 'Pakaian & Las': '#64748B', 'Peralatan Safety': '#2F9A58', Lainnya: '#94A3B8' };
const APD_STCOL = { Terlambat: '#C62828', Segera: '#F59E0B', Aman: '#2F9A58' };
const APD_BLN = { jan: 1, feb: 2, mar: 3, apr: 4, mei: 5, jun: 6, jul: 7, agu: 8, ags: 8, sep: 9, okt: 10, nov: 11, des: 12 };

/** Parser template "Pengelolaan APD dan Safety Devices" → { items, masuk, keluar, standar, harga, tahun, info }. */
function apdParseWb(XLS, wb) {
  const nz = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); const low = (s) => nz(s).toLowerCase();
  const sh = (n) => { const k = wb.SheetNames.find((x) => low(x) === n); return k ? wb.Sheets[k] : null; };
  const aoa = (ws) => XLS.utils.sheet_to_json(ws, { header: 1, raw: true, defval: '', blankrows: false });
  const num = (v) => { if (typeof v === 'number') return v; const s = String(v == null ? '' : v).replace(/[^\d,.-]/g, ''); return s ? parseFloat(s.replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')) || 0 : 0; };
  const out = { items: [], masuk: [], keluar: [], standar: [], harga: {}, tahun: 0, info: [] }; const yrs = {};
  const isoD = (v, y) => { if (v instanceof Date) return new Date(Math.round((v.getTime() - v.getTimezoneOffset() * 60000) / 86400000) * 86400000).toISOString().slice(0, 10); if (typeof v === 'number' && v > 20000) return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
    const s = nz(v); let m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s); if (m) return m[0]; m = /^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})/.exec(s); if (m) return `${m[3].length === 2 ? '20' + m[3] : m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
    m = /^(\d{1,2})\s+([A-Za-z]+)\.?\s*(\d{4})?/.exec(s); if (m) { const mo = APD_BLN[m[2].toLowerCase().slice(0, 3)]; if (mo) return `${m[3] || y}-${String(mo).padStart(2, '0')}-${m[1].padStart(2, '0')}`; } return ''; };
  const dist = sh('distribusi apd');
  if (dist) { const rows = aoa(dist); rows.forEach((r) => r.forEach((c) => { if (c instanceof Date) { const y = c.getFullYear(); if (y >= 2000 && y <= 2100) yrs[y] = (yrs[y] || 0) + 1; } })); }
  out.tahun = +(Object.keys(yrs).sort((a, b) => yrs[b] - yrs[a])[0] || new Date().getFullYear());
  // item & stok dari sheet bulan
  const months = Object.keys(APD_BLN).filter((k) => k !== 'agu'); const minBy = {}; const names = {};
  months.forEach((mk) => { const ws = sh(mk); if (!ws) return; const rows = aoa(ws); const hi = rows.findIndex((r) => /nama.*apd/i.test(String(r[1]))); if (hi < 0) return; const mo = APD_BLN[mk];
    rows.slice(hi + 1).forEach((r) => { const nama = nz(r[1]); if (!nama || /^total/i.test(nama) || !nz(r[2])) return; const key = nama.toLowerCase(); if (!names[key]) names[key] = { nama, satuan: nz(r[2]) || 'Pcs', saldo: 0, min: 0 };
      if (mk === 'jan') names[key].saldo = num(r[3]); const mn = num(r[5]); if (mn > 0) names[key].min = mn; const ms = num(r[4]); if (ms > 0) out.masuk.push({ nama, ym: `${out.tahun}-${String(mo).padStart(2, '0')}`, jumlah: ms }); }); });
  out.items = Object.keys(names).map((k) => names[k]);
  if (dist) { const rows = aoa(dist); const hi = rows.findIndex((r) => r.some((c) => /^nama$/i.test(nz(c))) && r.some((c) => /jenis apd/i.test(nz(c)))); if (hi >= 0) { const H = rows[hi].map((c) => low(c)); const ix = (re) => H.findIndex((h) => re.test(h)); const C = { tgl: ix(/^tanggal/), nama: ix(/^nama$/), nik: ix(/^nik/), pos: ix(/^posisi/), item: ix(/jenis apd/), jml: ix(/^jumlah/), kat: ix(/^kategori/) };
    rows.slice(hi + 1).forEach((r) => { const nama = nz(r[C.nama]); if (!nama || /^\d+$/.test(nama)) return; const jml = num(r[C.jml]); if (!nz(r[C.item]) && !jml && !nz(r[C.tgl])) return; out.keluar.push({ tanggal: isoD(r[C.tgl], out.tahun), tanggal_asli: nz(r[C.tgl] instanceof Date ? '' : r[C.tgl]), nama, nik: nz(r[C.nik]).replace(/\.0$/, ''), posisi: nz(r[C.pos]), item: nz(r[C.item]), jumlah: jml || 1, kategori: /sub/i.test(nz(r[C.kat])) ? 'Subkon' : 'HMSI' }); }); } }
  const usia = sh('usia-apd');
  if (usia) { const rows = aoa(usia); const hi = rows.findIndex((r) => r.some((c) => /^jabatan$/i.test(nz(c))) && r.some((c) => /helm/i.test(nz(c)))); if (hi >= 0) { const H = rows[hi].map((c) => low(c)); const ci = (re) => H.findIndex((h) => re.test(h)); const jc = ci(/^jabatan$/); const K = { helm: ci(/helm/), sepatu: ci(/shoes|sepatu/), kacamata: ci(/glass|kacamata/), masker: ci(/masker/), rompi: ci(/rompi/) }; let kel = 'Staff', stop = false;
    const dur = (v) => { const s = nz(v).toLowerCase(); const m = /(\d+(?:[.,]\d+)?)\s*(th|tahun|bl|bulan)/.exec(s); if (!m) return 0; const n = parseFloat(m[1].replace(',', '.')); return /^t/.test(m[2]) ? Math.round(n * 12) : Math.round(n); };
    rows.slice(hi + 1).forEach((r) => { const jb = nz(r[jc]); if (!jb || stop) return; if (/^harga/i.test(jb)) { stop = true; return; } if (/^non staff$/i.test(jb)) { kel = 'Non Staff'; return; } if (/^staff$/i.test(jb)) { kel = 'Staff'; return; } const d = { helm: dur(r[K.helm]), sepatu: dur(r[K.sepatu]), kacamata: dur(r[K.kacamata]), masker: dur(r[K.masker]), rompi: dur(r[K.rompi]) }; if (Object.keys(d).some((k) => d[k])) out.standar.push(Object.assign({ kelompok: kel, jabatan: jb }, d)); });
    const map = { sepatu: 'Sepatu', helm: 'Helm', rompi: 'Rompi', masker: 'Masker', kacamata: 'Kacamata' }; rows.forEach((r) => { const lb = low(r[1]); if (map[lb]) { const p = num(r[4]); if (p > 0) out.harga[map[lb]] = p; } }); } }
  out.info = [`Tahun ${out.tahun}`, `${out.items.length} item stok`, `${out.masuk.length} penerimaan`, `${out.keluar.length} distribusi`];
  return out;
}
async function apdImportDlg(done) {
  await loadXlsxLib(); let data = null;
  const m = modal({ title: 'Impor dari template Pengelolaan APD', size: 'lg', body: `<p class="sub mb16">Pilih berkas Excel template <b>Pengelolaan APD dan Safety Devices</b> (.xlsx). Yang dibaca: daftar item dan stok awal/minimum (sheet bulan), penerimaan per bulan, <b>Distribusi APD</b>, serta harga satuan. Standar umur pakai mengikuti <b>Matriks APD HMSI</b> (DOK III-004), bukan sheet USIA-APD. Impor aman diulang: data yang sama tidak digandakan.</p>
    <div class="drop" id="apDrop">${ic('upload_file', 's24')}<div class="b mt8" id="apT">Klik untuk memilih berkas .xlsx</div></div><div id="apR" class="mt16"></div>`, foot: `<button class="btn" data-x>Tutup</button><button class="btn pri" id="apOk" disabled>${ic('cloud_upload')}Impor sekarang</button>` });
  const show = (r) => { const h = r.hasil; $('#apR', m.el).innerHTML = `<div class="grid g-kpi">${kpi('Item baru', fmtN(h.item.baru), 'add_circle', 'okk')}${kpi('Item diperbarui', fmtN(h.item.ubah), 'sync', 'inf')}${kpi('Distribusi baru', fmtN(h.keluar.baru), 'outbox', 'okk')}${kpi('Penerimaan baru', fmtN(h.masuk.baru), 'inbox', 'okk')}</div>${h.keluar.lewati ? `<div class="note warn mt12">${ic('warning')}<div>${fmtN(h.keluar.lewati)} baris distribusi dilewati (sudah pernah diimpor atau datanya tidak lengkap).</div></div>` : ''}${r.nPeringatan ? `<div class="note warn mt12">${ic('warning')}<div class="grow"><b>${r.nPeringatan} perlu dicek</b><ul class="small" style="margin:6px 0 0 18px">${r.peringatan.slice(0, 12).map((x) => `<li>${esc(x)}</li>`).join('')}</ul></div></div>` : ''}`; };
  $('#apDrop', m.el).onclick = async () => {
    const fs = await pickFiles('.xlsx,.xls', false); if (!fs[0]) return; $('#apT', m.el).textContent = fs[0].name + ' · membaca…';
    try { const wb = XLSX.read(await fs[0].arrayBuffer(), { type: 'array', cellDates: true }); data = apdParseWb(XLSX, wb); } catch (e) { return toast('Berkas tidak dapat dibaca: ' + e.message, 'bad'); }
    if (!data.items.length && !data.keluar.length) return toast('Format template tidak dikenali (sheet bulan / Distribusi APD tidak ditemukan).', 'warn');
    $('#apT', m.el).textContent = fs[0].name + ' · ' + data.info.join(' · ');
    try { show(await API.run('apd.import', Object.assign({ mode: 'dry' }, data))); $('#apOk', m.el).disabled = false; } catch (e) { toast(e.message, 'bad'); }
  };
  $('#apOk', m.el).onclick = async (e) => { if (!data) return; const r = await busy(e.currentTarget, () => API.run('apd.import', Object.assign({ mode: 'commit' }, data), uid())); if (r) { m.close(); toast(`Impor selesai: ${r.hasil.item.baru + r.hasil.item.ubah} item, ${r.hasil.keluar.baru} distribusi.`, 'ok'); Data.drop('apd'); if (done) done(); } };
}

