/* ══ Persetujuan elektronik: PIN, lembar pengesahan PDF (QR + SHA-256), halaman verifikasi publik ══ */
function esignLoadScript(url) { return new Promise((res, rej) => { const s = document.createElement('script'); s.src = url; s.onload = res; s.onerror = () => rej(new Error('Pustaka tidak dapat dimuat (periksa koneksi).')); document.head.appendChild(s); }); }
async function esignLibs() { if (!window.PDFLib) await esignLoadScript('https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js'); if (!window.qrcode) await esignLoadScript('https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.js'); }
const esT = (t) => String(t == null ? '' : t).replace(/[–—]/g, '-').replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[^\x20-\x7E -ÿ]/g, '?');
