  txt('LEMBAR PENGESAHAN ELEKTRONIK', 40, 842 - 44, { size: 18, font: fb, color: rgb(1, 1, 1) }); txt("MY HOMS - Hanwha Orange's Management System", 40, 842 - 64, { size: 9.5, color: rgb(0.72, 0.77, 0.83) });
  let y = 842 - 122; const row = (l, v) => { txt(l, 40, y, { size: 9, color: mut }); const ls = wrap(v || '-', fb, 10.5, 380); ls.forEach((ln, i) => txt(ln, 150, y - i * 14, { font: fb, size: 10.5 })); y -= Math.max(1, ls.length) * 14 + 6; };
