  const cols = [40, 118, 300, 440]; ['Peran', 'Nama dan jabatan', 'Tindakan', 'Waktu (WIB)'].forEach((h, i) => txt(h, cols[i], y, { font: fb, size: 8.5, color: mut })); y -= 8; page.drawLine({ start: { x: 40, y }, end: { x: W - 40, y }, thickness: 0.5, color: line }); y -= 16;
  (e.signers || []).forEach((s) => { txt(s.peran, cols[0], y, { font: fb, size: 10 }); const nl = wrap(s.nama, fb, 10, 170); nl.forEach((ln, i) => txt(ln, cols[1], y - i * 12, { font: fb, size: 10 })); const jl = wrap(s.jabatan || '', f, 8.5, 170); jl.slice(0, 2).forEach((ln, i) => txt(ln, cols[1], y - nl.length * 12 - i * 11 + 1, { size: 8.5, color: mut })); wrap(s.aksi, f, 9, 130).forEach((ln, i) => txt(ln, cols[2], y - i * 12, { size: 9 })); txt(esWib(s.at), cols[3], y, { size: 9, font: fm });
    const h = nl.length * 12 + Math.min(2, jl.length) * 11 + 10; y -= Math.max(34, h); page.drawLine({ start: { x: 40, y: y + 12 }, end: { x: W - 40, y: y + 12 }, thickness: 0.4, color: line }); });
  y -= 6; wrap('Dokumen ini disetujui secara elektronik melalui sistem MY HOMS. Setiap persetujuan dikonfirmasi dengan PIN pribadi penandatangan dan dicatat dengan waktu server. Keabsahan dokumen dapat diperiksa dengan memindai kode QR atau membuka tautan verifikasi di bawah.', f, 9, W - 80).forEach((ln, i) => txt(ln, 40, y - i * 12.5, { size: 9, color: mut })); y -= 52;
  const by = y - 150; page.drawRectangle({ x: 40, y: by, width: W - 80, height: 150, borderColor: line, borderWidth: 1, color: rgb(0.985, 0.988, 0.992) });
