  txt('TAUTAN VERIFIKASI', 56, by + 84, { font: fb, size: 8.5, color: mut }); wrap(e.url || '-', fm, 7.5, 300).slice(0, 3).forEach((ln, i) => txt(ln, 56, by + 71 - i * 10, { font: fm, size: 7.5 }));
