  m = /(\d{1,2})\s*(?:[\-–—]\s*\d{1,2})?\s+([A-Za-z]+)\s+(\d{4})/.exec(t);
  if (m && MOM_BLN[m[2].toLowerCase()]) return m[3] + '-' + ('0' + MOM_BLN[m[2].toLowerCase()]).slice(-2) + '-' + ('0' + m[1]).slice(-2);
  m = /([A-Za-z]+)\s+(\d{4})/.exec(t);
